const V1124_COMMENTS = {"SoulMaster|生命淨化":{"tags":["新增"],"comment":"為了讓以近身戰鬥為主的聖魂劍士能穩定成長，新增與冒險家劍士相同的「生命淨化」。提高HP自然恢復量，減輕初期培養過程中的生存負擔。","notes":[]},"SoulMaster|生命擴展":{"tags":["新增"],"comment":"這是讓聖魂劍士作為可成長至200級的劍士職業，能確保足夠基礎HP的核心成長被動技能。","notes":[]},"SoulMaster|靈魂":{"tags":["新增"],"comment":"為了展現聖魂劍士運用靈魂之力的特色，讓玩家能召喚守護自身的精靈「靈魂」。靈魂精靈會以聖屬性攻擊周圍的敵人，並在召喚期間提高物理與魔法防禦力，同時輔助攻擊與生存。","notes":[["召喚","召喚靈魂精靈，以聖屬性攻擊周圍最多3名敵人。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["精靈攻擊力","無","21~40"],["物理防禦力與魔法防禦力增加","無","10~25"],["持續時間","無","158~300秒"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["精靈攻擊力","無","40","新增"],["持續時間","無","300秒","新增"]]},{"name":"物理、魔法防禦力增加","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","10","新增"],["Lv.6~10","無","15","新增"],["Lv.11~15","無","20","新增"],["Lv.16~20","無","25","新增"]]}]}]},"SoulMaster|自身強化":{"tags":["新增"],"comment":"為了提供近身戰鬥所需的基本防禦能力與移動便利性，新增與冒險家劍士相同的「自身強化」。提高物理防禦力與移動速度，支援初期的練功與移動。","notes":[],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["物理防禦力增加","無","40","新增"],["移動速度增加","無","10","新增"],["持續時間","無","300秒","新增"]]}]}]},"SoulMaster|魔天一擊":{"tags":["新增"],"comment":"為了讓聖魂劍士作為使用劍的劍士能習得熟悉的攻擊方式，提供了對單一敵人施展一擊的基本劍術。以此為起點，設計為可隨轉職階段使用更多樣的劍術。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","165~260%"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["傷害","無","260%","新增"]]}]}]},"SoulMaster|劍氣縱橫":{"tags":["新增"],"comment":"為了提供對付多隻怪物的基本練功能力，新增「劍氣縱橫」。這是可攻擊周圍最多6名敵人的劍術，設計為可依情況區分運用單一目標攻擊與多目標攻擊。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","72~130%最多6名"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["傷害","無","130%","新增"]]}]}]},"SoulMaster|精準之劍":{"tags":["新增"],"comment":"新增提高單手劍與雙手劍熟練度及命中率的「精準之劍」。提供與冒險家狂戰士相同的效果。","notes":[]},"SoulMaster|快速之劍":{"tags":["新增"],"comment":"新增使劍的攻擊速度提升一個階段的「快速之劍」。可在裝備單手劍或雙手劍的狀態下使用。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["攻擊速度","無","提升1階段"],["持續時間","無","15~300秒"]]}]},"SoulMaster|終極攻擊":{"tags":["新增"],"comment":"為了承襲劍士在劍術攻擊後接續追加打擊的戰鬥特色，新增「終極攻擊」。增益效果持續期間，使用攻擊技能後有一定機率發動追加攻擊，為基本劍術增添連續攻擊的效果。","notes":[["發動","使用魔天一擊或劍氣縱橫時，有一定機率發動追加攻擊。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["觸發機率","無","2~60%"],["追加攻擊傷害","無","105~250%使用魔天一擊時"],["多目標追加攻擊傷害","無","63~150%使用劍氣縱橫時"],["持續時間","無","155~300秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["觸發機率","無","60%","新增"],["追加攻擊傷害（1名）","無","250%","新增"],["追加攻擊傷害（多名）","無","150%","新增"],["持續時間","無","300秒","新增"]]}]}]},"SoulMaster|靈魂守護者":{"tags":["新增"],"comment":"為了讓聖魂劍士擁有與其他劍士有所區別的獨特防禦能力，新增以靈魂之力將所受傷害的一部分改由MP承擔的「靈魂守護者」。藉此減少近身戰鬥中的HP消耗，並設計為可透過三轉習得的「靈體同化」進一步強化該效果。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["以MP代替承受的傷害","無","1~10%"],["持續時間","無","47~300秒"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["以MP代替承受的傷害","無","10%","新增"],["持續時間","無","300秒","新增"]]}]}]},"SoulMaster|靈魂之刃":{"tags":["新增"],"comment":"這是展現聖魂劍士特色的「靈魂之刃」，將無形的靈魂之力化為劍術射向敵人。作為原作的代表性技能之一，新增為聖魂劍士的主力技能。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","95~180%"],["最大攻擊目標數量","無","3~5名"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["傷害","無","180%","新增"]]},{"name":"最大攻擊目標數量","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","無","3名","新增"],["Lv.11~20","無","4名","新增"],["Lv.21~30","無","5名","新增"]]},{"name":"射程","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","無","2格","新增"],["Lv.11~20","無","2.5格","新增"],["Lv.21~30","無","3格","新增"]]}]}]},"SoulMaster|靈魂迅移":{"tags":["新增"],"comment":"新增可在空中再次躍進的移動技能「靈魂迅移」。可借助靈魂之力快速向前方移動。","notes":[]},"SoulMaster|魔力恢復":{"tags":["新增"],"comment":"新增提高MP自然恢復量的「魔力恢復」。有助於管理使用攻擊技能與靈魂守護者時所需的MP。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["MP自然恢復","無","+2~30"]]}]},"SoulMaster|體能訓練":{"tags":["新增"],"comment":"新增永久增加物理防禦力的「體能訓練」。透過身體鍛鍊強化近身戰鬥所需的防禦能力。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["物理防禦力增加","無","+12~70"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["物理防禦力增加","無","70","新增"]]}]}]},"SoulMaster|靈體同化":{"tags":["新增"],"comment":"為了進一步強化聖魂劍士運用靈魂之力的防禦能力，新增「靈體同化」。提高原有「靈魂守護者」以MP代為承擔的傷害比例，並減少代為承受傷害時消耗的MP，使玩家能更有效率地運用生存能力。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["增加以MP代替承受的傷害","無","+1~10%"],["以MP代替承受傷害時的MP消耗降低","無","10~50%"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["增加以MP代替承受的傷害","無","10%","新增"],["消耗MP降低","無","50%","新增"]]}]}]},"SoulMaster|進階靈魂":{"tags":["新增"],"comment":"為了讓聖魂劍士在成長過程中體驗與靈魂精靈更緊密配合的戰鬥，新增「進階靈魂」。取代原本的精靈召喚，改為套用在一定時間內運用精靈之力的增益效果，並變更為對所攻擊的一般怪物有機率觸發靈魂的追加打擊。","notes":[["使用靈魂","每次使用靈魂會消耗1顆召喚石，並以進階靈魂增益效果取代精靈召喚。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["追加攻擊機率","無","10~70%"],["追加攻擊傷害","無","45~75%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["追加攻擊機率","無","70%","新增"],["追加攻擊傷害","無","75%","新增"]]}]}]},"SoulMaster|靈魂鬥氣":{"tags":["新增"],"comment":"為了將劍士系列連續使用劍術、逐步施展更強攻擊的特色也套用於聖魂劍士，新增「靈魂鬥氣」。設計為每次攻擊時累積鬥氣量，並依鬥氣量提高傷害，使持續的攻擊能延續為強力的劍術；同時設計了與對應的「鬥氣集中」略有不同的機制與演出。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["最大鬥氣量","無","1~3個"],["每1個鬥氣量的傷害","無","+1~20%"],["持續時間","無","120~300秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["每1個的傷害","無","20%","新增"],["累積至上限時的傷害","無","1.60倍","新增"],["持續時間","無","300秒","新增"]]},{"name":"最大鬥氣量","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~8","無","1個","新增"],["Lv.9~22","無","2個","新增"],["Lv.23~30","無","3個","新增"]]}]}]},"SoulMaster|靈魂斬":{"tags":["新增"],"comment":"新增可快速斬擊敵人兩次的連續劍術「靈魂斬」。隨著技能成長，攻擊目標數會增加，可連續攻擊鄰近的敵人。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","88~170%攻擊2次"],["最大攻擊目標數量","無","1~2名"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["傷害","無","170%","新增"]]},{"name":"最大攻擊目標數量","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~15","無","1名","新增"],["Lv.16~30","無","2名","新增"]]}]}]},"SoulMaster|靈魂屬性":{"tags":["新增"],"comment":"為了強化聖魂劍士身為運用聖屬性之劍士的特色，新增「靈魂屬性」。在一定時間內為劍賦予聖屬性，使所有攻擊皆套用聖屬性，並設計為面對聖屬性弱點的怪物時能施展更有效的攻擊。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","101~120%"],["持續時間","無","110~300秒"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["傷害","無","120%","新增"],["持續時間","無","300秒","新增"]]}]}]},"SoulMaster|西格諾斯騎士":{"tags":["新增"],"comment":"為了讓皇家騎士團作為可成長至200級的職業具備所需的四轉能力，新增「西格諾斯騎士」。藉由覺醒女皇的祝福強化自身與隊員的所有能力值，並提供與冒險家的「楓葉祝福」相同的效果。","notes":[],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["所有能力值增加","無","15%","新增"],["持續時間","無","900秒","新增"]]}]}]},"SoulMaster|格擋":{"tags":["新增"],"comment":"為了讓聖魂劍士在四轉之後與強大的BOSS怪物戰鬥時也能穩定地持續攻擊，新增「格擋」。與冒險家劍士相同，不被擊退的機率會隨技能等級提高，滿級時提供100%的不被擊退機率。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["不被擊退的機率","無","35~100%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["不被擊退的機率","無","100%","新增"],["持續時間","無","300秒","新增"]]}]}]},"SoulMaster|靈魂迴響":{"tags":["新增"],"comment":"為了表現聖魂劍士將周圍消逝的靈魂迴響化為自身力量的特色，新增「靈魂迴響」。透過每當怪物倒下時累積的迴響強化劍術的威力，提供運用靈魂之力的全新練功體驗。","notes":[["迴響","每層迴響持續5秒。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["迴響層數上限","無","6~20個"],["每1層迴響的傷害","無","+1%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["迴響層數上限","無","20個","新增"]]}]}]},"SoulMaster|守護者之甲":{"tags":["新增"],"comment":"為了強化聖魂劍士應對敵人魔法攻擊的防禦能力，新增「守護者之甲」。受到魔法攻擊時，有一定機率將與所受傷害成比例的傷害反彈給敵人，使玩家在承受攻擊的過程中也能反擊。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["觸發機率","無","31~60%"],["反彈傷害","無","所受傷害的55~200%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["觸發機率","無","60%","新增"],["反彈傷害","無","200%","新增"]]}]}]},"SoulMaster|靈魂突刺":{"tags":["新增"],"comment":"為了讓聖魂劍士在四轉之後也能持續施展運用靈魂之力的強力多目標攻擊，新增「靈魂突刺」。作為原作聖魂劍士的強力技能，配合將靈魂鍛鍊至極限的騎士概念，進一步改善了性能。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","88~175%攻擊4次"],["最大攻擊目標數量","無","3~8名"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["傷害","無","175%","新增"],["橫向範圍","無","7.25格","新增"]]},{"name":"最大攻擊目標數量","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","3名","新增"],["Lv.6~10","無","4名","新增"],["Lv.11~15","無","5名","新增"],["Lv.16~20","無","6名","新增"],["Lv.21~25","無","7名","新增"],["Lv.26~30","無","8名","新增"]]},{"name":"MP消耗","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","無","150","新增"],["Lv.11~20","無","250","新增"],["Lv.21~30","無","350","新增"]]}]}]},"SoulMaster|英勇狂斬":{"tags":["新增"],"comment":"新增對單一敵人施展三次連續攻擊的「英勇狂斬」。這是面對強大單一目標時運用的四轉劍術。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","116~160%攻擊1名敵人3次"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["傷害","無","160%","新增"]]}]}]},"SoulMaster|魂之劍":{"tags":["新增"],"comment":"為了讓聖魂劍士作為運用聖屬性的劍士也能在組隊戰鬥中有所貢獻，新增「魂之劍」。將自身的靈魂注入武器，強化周圍隊員的聖屬性攻擊傷害，提供將靈魂之力擴及我方的支援能力。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["聖屬性額外傷害","無","+1~20%"],["持續時間","無","40~300秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["聖屬性額外傷害","無","20%","新增"],["持續時間","無","300秒","新增"]]}]}]},"SoulMaster|楓葉淨化":{"tags":["新增"],"comment":"為了讓聖魂劍士在四轉後能應對危險的異常狀態，新增與冒險家相同的「楓葉淨化」。可解除誘惑、封印等特定異常狀態，協助玩家持續戰鬥。","notes":[]},"FlameWizard|魔力淨化":{"tags":["新增"],"comment":"為了讓烈焰巫師作為運用魔法的職業能穩定成長，新增與冒險家法師相同的「魔力淨化」。提高MP自然恢復量，提供持續使用魔法所需的基本成長能力。","notes":[]},"FlameWizard|魔力擴展":{"tags":["新增"],"comment":"為了讓烈焰巫師在成長至200級的過程中能運用多樣的火焰魔法，新增與冒險家法師相同的「魔力擴展」。提高升級時增加的MaxMP，為長期培養法師奠定所需的成長基礎。","notes":[]},"FlameWizard|魔心防禦":{"tags":["新增"],"comment":"為了讓烈焰巫師在各種戰鬥中能穩定生存，新增與冒險家法師相同的「魔心防禦」。將所受傷害的一部分改由MP承擔，提供法師所需的基本生存能力。","notes":[]},"FlameWizard|魔力之盾":{"tags":["新增"],"comment":"為了讓烈焰巫師具備基本的防禦能力，新增與冒險家法師相同的「魔力之盾」。運用魔力提高物理防禦力，支援初期培養過程中的生存。","notes":[]},"FlameWizard|火牢術":{"tags":["新增"],"comment":"這是烈焰巫師的象徵「火牢術」。召喚出的精靈會以火屬性魔法攻擊周圍的敵人，並提高烈焰巫師的物理與魔法防禦力。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["攻擊","無","最多攻擊3名敵人"],["基礎攻擊力","無","10~20"],["持續時間","無","158~300秒"],["物理防禦力與魔法防禦力增加","無","10~25"],["燃燒","無","40~80%機率，持續11~20秒已學習烈焰智慧時"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["基礎攻擊力","無","20","新增"],["熟練度","無","60%","新增"],["持續時間","無","300秒","新增"],["燃燒機率","無","80%","新增"],["燃燒時間","無","20秒","新增"]]},{"name":"精靈防禦力 （物理、魔法）","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","10","新增"],["Lv.6~10","無","15","新增"],["Lv.11~15","無","20","新增"],["Lv.16~20","無","25","新增"]]}]}]},"FlameWizard|魔力爪":{"tags":["新增"],"comment":"為了讓烈焰巫師從初期就能運用火焰魔法，新增「魔力爪」。這是攻擊前方敵人兩次的火屬性魔法，之後習得「烈焰智慧」時，還能運用燃燒效果。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["攻擊","無","最多攻擊2名敵人，每名2次"],["基礎攻擊力","無","5.5~20"],["燃燒","無","40~80%機率，持續11~20秒已學習烈焰智慧時"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["基礎攻擊力","無","20.0","新增"],["熟練度","無","55%","新增"],["燃燒機率 （每次攻擊）","無","80%","新增"],["燃燒時間","無","20秒","新增"]]}]}]},"FlameWizard|烈焰智慧":{"tags":["新增"],"comment":"為了強化烈焰巫師運用火屬性魔法與持續傷害的特色，新增「烈焰智慧」。可透過火屬性攻擊對敵人施加「燃燒」，被燃燒的敵人會在一定時間內持續受到火焰傷害。藉此提供同時運用直接攻擊與持續傷害的戰鬥方式。","notes":[["新增燃燒","陷入燃燒狀態的敵人每1秒受到火屬性魔法傷害。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["燃燒基礎攻擊力","無","0.5~2.5"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["燃燒基礎攻擊力","無","2.5","新增"]]}]}]},"FlameWizard|精神強力":{"tags":["新增"],"comment":"新增提高自身與隊員魔力的「精神強力」。提供與冒險家法師相同的效果，將技能提升至最高等級後，也會新增至祝福技能中。","notes":[["新增祝福的精神強化","將精神強力提升至20級後，將新增至帳號的祝福技能中。"]]},"FlameWizard|自然力重置":{"tags":["新增"],"comment":"為了讓使用屬性魔法的隊員能應對各種怪物的屬性抗性，新增「自然力重置」。增益效果持續期間，隊員的屬性魔法攻擊會轉為無屬性，得以避開原屬性的傷害減半與無效效果。不過，屬性弱點帶來的追加傷害與部分異常狀態效果也不會生效，因此設計為可依戰鬥情況選擇性運用的支援技能。","notes":[["轉為無屬性","所有屬性魔法攻擊都會變為無屬性。"],["異常狀態","轉為無屬性的攻擊無法造成中毒、冰凍或燃燒。"],["新增祝福的自然力重置","將自然力重置提升至20級後，將新增至帳號的祝福技能中。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["持續時間","無","110~300秒"]]}]},"FlameWizard|瞬間移動":{"tags":["新增"],"comment":"為了讓烈焰巫師在各種地形與戰鬥情況中能靈活移動，新增與冒險家法師相同的「瞬間移動」。這是之後在高階轉職中得以將移動與火焰攻擊相互銜接的基本移動能力。","notes":[]},"FlameWizard|烈焰箭":{"tags":["新增"],"comment":"新增以火焰之箭貫穿並攻擊前方最多3名敵人的「烈焰箭」。習得烈焰智慧後，也會套用燃燒效果。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["攻擊","無","最多貫穿攻擊3名敵人"],["基礎攻擊力","無","17~75"],["燃燒","無","40~80%機率，持續11~20秒已學習烈焰智慧時"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["基礎攻擊力","無","75","新增"],["熟練度","無","60%","新增"],["燃燒機率","無","80%","新增"],["燃燒時間","無","20秒","新增"]]}]}]},"FlameWizard|火柱":{"tags":["新增"],"comment":"為了讓玩家能多樣地運用與燃燒相互銜接的火焰攻擊，新增「火柱」。這是攻擊周圍最多6名敵人的魔法，並設計為對已被燃燒的怪物提高暴擊機率。藉此可區分運用施加燃燒的攻擊與攻擊已燃燒敵人的技能。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["攻擊","無","最多攻擊6名敵人"],["基礎攻擊力","無","42~80"],["對被燃燒的敵人暴擊機率增加","無","20~40%"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["基礎攻擊力","無","80","新增"],["熟練度","無","60%","新增"],["對被燃燒敵人的暴擊機率","無","40%","新增"]]}]}]},"FlameWizard|極速詠唱":{"tags":["新增"],"comment":"為了讓烈焰巫師能更快速地使用各種火焰魔法，新增「極速詠唱」。與冒險家法師相同，強化魔法攻擊速度，提供運用連續魔法攻擊所需的基本能力。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["持續時間","無","15~300秒"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["持續時間","無","300秒","新增"]]},{"name":"魔法攻擊速度","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","無","1階段","新增"],["Lv.11~20","無","2階段","新增"]]}]}]},"FlameWizard|烈焰精通":{"tags":["新增"],"comment":"為了讓火屬性魔法與燃燒能一同成長，新增「烈焰精通」。在提高火屬性攻擊傷害的同時強化燃燒的基本攻擊力，使烈焰巫師同時運用火焰攻擊與持續傷害的戰鬥能力得以進一步發展。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["火屬性額外傷害","無","1~10%"],["燃燒基礎攻擊力","無","2.5~12"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["火屬性額外傷害","無","10%","新增"],["燃燒基礎攻擊力","無","12.0","新增"]]}]}]},"FlameWizard|烈焰抵抗":{"tags":["新增"],"comment":"為了將烈焰巫師運用火屬性魔法的特色也反映在防禦能力上，新增「烈焰抵抗」。提高對敵人火屬性魔法攻擊的抗性，使玩家面對使用火焰的怪物時能更穩定地戰鬥。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["火屬性抗性","無","23~75%"]]}]},"FlameWizard|魔力激發":{"tags":["新增"],"comment":"為了讓烈焰巫師能使用更強力的魔法攻擊，新增與冒險家法師相同的「魔力激發」。以增加MP消耗量為代價強化攻擊魔法的傷害，藉此提高火焰攻擊能力。","notes":[],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["魔法傷害增加","無","50%","新增"],["消耗MP增加","無","100%","新增"],["持續時間","無","300秒","新增"]]}]}]},"FlameWizard|烈焰吸收":{"tags":["新增"],"comment":"為了表現烈焰巫師從留在敵人身上的火焰中吸取生命力的特色，新增「烈焰吸收」。每當自身引發的燃燒灼燒敵人時恢復HP，使火焰之力能同時運用於攻擊與生存。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["HP恢復","無","燃燒傷害的1~4%"]]}]},"FlameWizard|魔法封印":{"tags":["新增"],"comment":"為了讓烈焰巫師在突襲中也能支援隊伍的攻擊能力，新增「魔法封印」。降低周圍怪物的物理與魔法防禦力以輔助我方攻擊，並設計為對BOSS怪物也能生效。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["目標數量","無","最多6名"],["防禦力降低","無","20~40%"],["封印機率","無","38~95%"],["持續時間","無","10~20秒"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["防禦力降低","無","40%","新增"],["封印機率","無","95%","新增"],["持續時間","無","20秒","新增"]]}]}]},"FlameWizard|火牢術屏障":{"tags":["新增"],"comment":"烈焰巫師被設計為以大範圍火焰魔法對付多隻怪物的練功特化型法師。我們認為最能展現這項特色的原作代表技能就是「火牢術屏障」，因此將其承襲為此次烈焰巫師的核心攻擊技能。火牢術屏障會在一定區域設置火焰屏障，對範圍內的怪物反覆造成火焰傷害並施加燃燒。藉此不僅提供直接攻擊，也希望提供運用火焰屏障掌控練功場空間的戰鬥方式。此外，四轉時可進一步強化火焰屏障的攻擊能力，使原作的代表性技能在高等級階段也能發揮重要作用。","notes":[["火焰屏障","每1秒攻擊屏障內最多6名敵人。"],["火焰屏障攻擊的擊退","被火焰屏障的攻擊擊中的怪物不會被擊退。"],["火焰屏障攻擊次數","對同一目標每秒最多僅攻擊3次。"],["火焰屏障數量","不論施放者為誰，同一張地圖最多可設置6個火焰屏障。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["施放時的攻擊","無","最多攻擊6名敵人，每名1次"],["施放時攻擊的基礎攻擊力","無","8~22.5"],["火焰屏障基礎攻擊力","無","16~45"],["火焰屏障持續時間","無","4~40秒"],["燃燒","無","30~100%機率，持續15秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["施放時攻擊的基礎攻擊力","無","22.5","新增"],["火焰屏障基礎攻擊力","無","45","新增"],["熟練度","無","60%","新增"],["火焰屏障持續時間","無","40秒","新增"],["燃燒機率","無","100%","新增"]]}]}]},"FlameWizard|火焰吐息":{"tags":["新增"],"comment":"為了提高直接攻擊多隻怪物的火焰魔法的運用度，新增「火焰吐息」。向前方連續發射燃燒球體，攻擊最多6名敵人兩次，並有一定機率施加燃燒，還能造成持續的火焰傷害。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["攻擊","無","最多攻擊6名敵人，每名2次"],["基礎攻擊力","無","36.5~70"],["燃燒","無","41~70%機率，持續6~10秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["基礎攻擊力 （單次）","無","70.0","新增"],["熟練度","無","60%","新增"],["燃燒機率","無","70%","新增"]]},{"name":"燃燒時間","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~4","無","6秒","新增"],["Lv.5~11","無","7秒","新增"],["Lv.12~19","無","8秒","新增"],["Lv.20~26","無","9秒","新增"],["Lv.27~30","無","10秒","新增"]]}]}]},"FlameWizard|西格諾斯騎士":{"tags":["新增"],"comment":"為了讓皇家騎士團作為可成長至200級的職業具備所需的四轉能力，新增「西格諾斯騎士」。藉由覺醒女皇的祝福強化自身與隊員的所有能力值，並提供與冒險家的「楓葉祝福」相同的效果。","notes":[],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["所有能力值增加","無","15%","新增"],["持續時間","無","900秒","新增"]]}]}]},"FlameWizard|烈焰真理":{"tags":["新增"],"comment":"為了讓烈焰巫師在四轉之後能強化親自施放的火焰魔法的攻擊能力，新增「烈焰真理」。提高火屬性攻擊魔法的熟練度，強化親自施放之攻擊的穩定性，並設計為不適用於召喚獸與火牢術屏障的火焰屏障攻擊。此外，自己施加的燃燒傷害也有一定機率發生暴擊，不僅是直接攻擊，持續傷害的威力也能一併提升。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["熟練度增加","無","1~10%"],["燃燒暴擊機率","無","11~30%"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["熟練度增加","無","10%","新增"],["燃燒暴擊機率","無","30%","新增"]]}]}]},"FlameWizard|火步行":{"tags":["新增"],"comment":"為了表現火焰法師在踏過之處留下火焰的特色，新增「火步行」。使用瞬間移動後，在離開的位置會燃起火花攻擊周圍的敵人，實現了在移動的瞬間也能發揮火焰之力的戰鬥方式。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["攻擊","無","最多攻擊6名敵人，每名1次"],["基礎攻擊力","無","22~80"],["燃燒","無","43~100%機率，持續11~20秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["基礎攻擊力","無","80","新增"],["熟練度","無","60%","新增"],["燃燒機率","無","100%","新增"],["燃燒時間","無","20秒","新增"]]}]}]},"FlameWizard|火之書":{"tags":["新增"],"comment":"為了讓烈焰巫師在突襲中也能支援隊伍的攻擊能力，新增「火之書」。借助火焰的權能提高自身與周圍隊員的最終傷害，施放者的INT越高，效果越強。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["魔法石消耗","無","1個"],["最終傷害增加","無","施放者每1點INT提升0.018%"],["持續時間","無","11~40秒"],["冷卻時間","無","600~420秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["持續時間","無","40秒","新增"],["冷卻時間","無","420秒","新增"]]}]}]},"FlameWizard|火流星":{"tags":["新增"],"comment":"為了讓烈焰巫師在四轉之後能使用強力的大範圍火焰攻擊，新增「火流星」。套用與大魔導士（火、毒）的火流星相同的攻擊數值，並配合烈焰巫師的特色，設計為對命中的怪物施加燃燒。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["燃燒","無","100%機率，持續5秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["基礎攻擊力","無","570","新增"],["消耗MP","無","3500","新增"]]}]}]},"FlameWizard|火風暴":{"tags":["新增"],"comment":"為了讓烈焰巫師在四轉之後也能運用多樣的火焰攻擊，新增「火風暴」。這是攻擊前方最多6名敵人兩次的魔法，設計為可在造成直接火焰攻擊的同時施加燃燒。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["攻擊","無","最多攻擊6名敵人，每名2次"],["基礎攻擊力","無","26.5~73"],["燃燒","無","71~100%機率，持續1~5秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["基礎攻擊力 （單次）","無","73.0","新增"],["熟練度","無","80%","新增"],["燃燒機率","無","100%","新增"]]},{"name":"燃燒時間","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~4","無","1秒","新增"],["Lv.5~11","無","2秒","新增"],["Lv.12~19","無","3秒","新增"],["Lv.20~26","無","4秒","新增"],["Lv.27~30","無","5秒","新增"]]}]}]},"FlameWizard|火幕":{"tags":["新增"],"comment":"為了進一步強化作為烈焰巫師核心攻擊要素的燃燒與火牢術屏障，新增「火幕」。提高自身施加之燃燒的傷害，並使火牢術屏障的火焰屏障在攻擊被燃燒的敵人時提高暴擊機率與暴擊傷害，讓玩家在高階轉職後也能有效運用火牢術屏障。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["火焰屏障對被燃燒敵人的暴擊機率增加","無","21~50%"],["火焰屏障對被燃燒敵人的暴擊傷害","無","150~250%"],["燃燒基礎攻擊力","無","12~48"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["火焰屏障暴擊機率","無","50%","新增"],["火焰屏障暴擊傷害","無","250%","新增"],["燃燒基礎攻擊力","無","48.0","新增"]]}]}]},"FlameWizard|烈焰水靈":{"tags":["新增"],"comment":"新增召喚火焰綠水靈「烈焰水靈」的技能。烈焰水靈會攻擊周圍的敵人並施加燃燒，但無法與原有的火牢術精靈同時召喚。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["攻擊","無","最多攻擊3名敵人"],["召喚石消耗","無","1個"],["基礎攻擊力","無","34~200"],["持續時間","無","10~300秒"],["燃燒","無","100%機率，持續3~20秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["基礎攻擊力","無","200","新增"],["持續時間","無","300秒","新增"],["燃燒時間","無","20秒","新增"]]}]}]},"FlameWizard|楓葉淨化":{"tags":["新增"],"comment":"新增可解除特定異常狀態的「楓葉淨化」。提供與冒險家的「楓葉淨化」相同的效果。","notes":[]},"WindBreaker|精準強化":{"tags":["新增"],"comment":"為了讓玩家具備弓箭手所需的基本命中能力，新增「精準強化」。提供與冒險家弓箭手的「精準強化」相同的效果，支援穩定的弓箭攻擊。","notes":[]},"WindBreaker|霸王箭":{"tags":["新增"],"comment":"為了讓玩家能運用弓箭手職業的核心攻擊特色暴擊攻擊，新增「霸王箭」。提供與冒險家弓箭手相同的效果，並設計為之後習得的攻擊強化技能的基礎。","notes":[],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["暴擊機率","無","40%","新增"],["暴擊傷害","無","200%","新增"]]}]}]},"WindBreaker|百步穿楊":{"tags":["新增"],"comment":"為了讓使用弓的破風使者能發揮遠距離攻擊的優勢，新增「百步穿楊」。與冒險家弓箭手的「百步穿楊」相同，增加弓與弩的射程。","notes":[]},"WindBreaker|集中術":{"tags":["新增"],"comment":"為了讓破風使者能穩定命中弓箭攻擊並應對敵人的攻擊，新增「集中術」。與冒險家弓箭手相同，提供提高命中率與迴避率的效果。","notes":[]},"WindBreaker|暴風":{"tags":["新增"],"comment":"為了展現破風使者與風之精靈並肩作戰的特色，新增「暴風」。精靈會攻擊周圍的敵人並提高物理與魔法防禦力，並設計為之後在高階轉職中能將精靈之力發展為更強大的攻擊能力。","notes":[["召喚","召喚風之精靈，攻擊周圍最近的最多3隻敵人。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["精靈攻擊力","無","21~40"],["持續時間","無","158~300秒"],["物理防禦力與魔法防禦力增加","無","10~25"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["精靈攻擊力","無","40","新增"],["持續時間","無","300秒","新增"]]},{"name":"物理防禦力與魔法防禦力增加","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","10","新增"],["Lv.6~10","無","15","新增"],["Lv.11~15","無","20","新增"],["Lv.16~20","無","25","新增"]]}]}]},"WindBreaker|二連箭":{"tags":["新增"],"comment":"為了讓使用弓的破風使者能運用基本的連續射擊，新增「二連箭」。提供與冒險家弓箭手相同的攻擊性能，並設計為之後可透過「風影漫步」在空中使用。","notes":[],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["傷害","無","130%","新增"]]}]}]},"WindBreaker|精準之弓":{"tags":["新增"],"comment":"為了讓以弓為主力武器的破風使者具備穩定的攻擊能力，新增「精準之弓」。提供與冒險家獵人相同的熟練度及命中率增加效果。","notes":[]},"WindBreaker|快速之箭":{"tags":["新增"],"comment":"為了展現破風使者如風一般快速射箭的特色，提供強化弓攻擊速度的「快速之箭」。","notes":[],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["持續時間","無","300秒","新增"],["HP與MP消耗","無","10","新增"]]}]}]},"WindBreaker|風影漫步":{"tags":["新增"],"comment":"此次的破風使者跳脫了原有弓箭手的攻擊方式，設計為能快速移動並在空中自由射箭的職業。作為實現這種戰鬥方式的核心技能，新增了「風影漫步」，只要習得1級，就能在跳躍或下落途中使用主要的射擊技能。藉此，除了在地面站定位置攻擊的方式之外，也希望提供將跳躍與移動自然銜接至攻擊的破風使者專屬戰鬥體驗。","notes":[["空中射擊","跳躍或下落期間，也可使用二連箭、四連箭、箭雨、疾風光速神弩與疾風掃射。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["移動速度增加","無","1~10"]]}]},"WindBreaker|終極攻擊":{"tags":["新增"],"comment":"為了承襲弓箭手在弓箭攻擊後接續追加打擊的戰鬥特色，新增「終極攻擊」。使用攻擊技能後有一定機率額外射出一支箭矢，並提供與冒險家獵人相同的傷害結構。","notes":[["發動","使用二連箭時，有一定機率追加發射一支箭。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["觸發機率","無","2~60%"],["持續時間","無","155~300秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["觸發機率","無","60%","新增"],["追加箭矢傷害","無","250%","新增"],["持續時間","無","300秒","新增"]]}]}]},"WindBreaker|無形之箭":{"tags":["新增"],"comment":"為了讓破風使者能應對防禦力高的怪物，新增「無形之箭」。與冒險家獵人相同，為弓箭攻擊賦予無視防禦力效果，補強攻擊能力。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["持續時間","無","15~300秒"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["持續時間","無","300秒","新增"]]},{"name":"無視防禦力","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","1%","新增"],["Lv.6~10","無","2%","新增"],["Lv.11~15","無","3%","新增"],["Lv.16~20","無","4%","新增"]]}]}]},"WindBreaker|暴風射擊":{"tags":["新增"],"comment":"為了展現破風使者以強風推開靠近之敵人的特色，新增「暴風射擊」。表現出以風之力擊退敵人後再次拉弓瞄準的戰鬥方式。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","65~160%"],["擊退機率","無","43~100%"],["攻擊目標數量","無","3~6名"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["傷害","無","160%","新增"],["擊退機率","無","100%","新增"]]},{"name":"攻擊目標數量","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~7","無","3隻","新增"],["Lv.8~15","無","4隻","新增"],["Lv.16~22","無","5隻","新增"],["Lv.23~30","無","6隻","新增"]]}]}]},"WindBreaker|阿爾法之眼":{"tags":["新增"],"comment":"為了將破風使者兼具快速移動與遠距離射擊的職業特色也連結至攻擊能力，新增「阿爾法之眼」。設計為在阿爾法狀態下，與敵人的橫向距離越遠，無視的物理防禦力越多，使玩家不只是單純射箭，還能運用調整與敵人之間距離進行攻擊的戰鬥方式。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["每100距離無視的物理防禦力","無","3~10%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["每100距離無視的物理防禦力","無","10%","新增"]]}]}]},"WindBreaker|疾風步":{"tags":["新增"],"comment":"為了支援以快速移動為核心進行戰鬥的破風使者的機動性，新增「疾風步」。與冒險家遊俠相同，提供提高移動速度的效果。","notes":[]},"WindBreaker|致命箭":{"tags":["新增"],"comment":"新增無視敵人部分防禦力並提高「箭雨」傷害的「致命箭」。效果與冒險家遊俠相同。","notes":[]},"WindBreaker|替身術":{"tags":["新增"],"comment":"為了讓破風使者能在遠距離更穩定地戰鬥，新增「替身術」。與冒險家遊俠相同，提供在一定範圍內代為承受部分所受傷害的召喚效果。","notes":[]},"WindBreaker|阿爾法":{"tags":["新增"],"comment":"在承襲原作破風使者的代表性特色「阿爾法」之力的同時，也希望盡量減少因變身而遮蔽角色外觀的不便。  因此，將原本的變身方式重新設計為維持角色外觀的強化增益效果。在阿爾法狀態下，防禦力與移動能力會提高，並可運用依距離無視防禦力的效果與專屬攻擊技能。藉此在保留原作特色戰鬥概念的同時，設計為四轉之後也能持續進行更自由的射擊與移動。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["召喚石消耗","無","1個"],["物理防禦力與魔法防禦力增加","無","10~50"],["移動速度與跳躍力增加","無","移動速度+40，跳躍力+20"],["持續時間","無","120~300秒"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["物理防禦力與魔法防禦力增加","無","50","新增"],["持續時間","無","300秒","新增"],["MP消耗","無","70","新增"]]}]}]},"WindBreaker|四連箭":{"tags":["新增"],"comment":"為了讓破風使者從三轉開始就能運用強力的單一目標連續射擊，新增「四連箭」。提供與冒險家遊俠相同的攻擊性能，並設計為可透過風影漫步在空中使用。","notes":[],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["傷害","無","100%","新增"],["額外暴擊機率","無","30%","新增"],["攻擊BOSS時的傷害","無","20%","新增"]]}]}]},"WindBreaker|箭雨":{"tags":["新增"],"comment":"為了能有效率地攻擊聚集在周圍的怪物，新增「箭雨」。在空中也能使用，可運用於移動中攻擊多名敵人的練功。","notes":[["攻擊","最多攻擊周圍6隻敵人。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","65~160%"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["傷害","無","160%","新增"]]}]}]},"WindBreaker|西格諾斯騎士":{"tags":["新增"],"comment":"為了讓皇家騎士團作為可成長至200級的職業具備所需的四轉能力，新增「西格諾斯騎士」。藉由覺醒女皇的祝福強化自身與隊員的所有能力值，並提供與冒險家的「楓葉祝福」相同的效果。","notes":[],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["所有能力值增加","無","15%","新增"],["持續時間","無","900秒","新增"]]}]}]},"WindBreaker|弓術精通":{"tags":["新增"],"comment":"為了讓可成長至200級的破風使者在高階轉職後也能強化弓箭攻擊的性能，提供了提高熟練度與物理攻擊力的被動技能。","notes":[]},"WindBreaker|身輕如羽":{"tags":["新增"],"comment":"為了強化破風使者借助風之力快速移動的特色，新增「身輕如羽」。提高移動速度上限，使其能比其他職業更快速地移動，並設計為可與風影漫步搭配運用，將移動與射擊自然銜接。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["移動速度上限增加","無","1~20"]]}]},"WindBreaker|風之祈禱":{"tags":["新增"],"comment":"破風使者被設計為運用快速移動與連續射擊的弓箭手。為了強化這項特色，新增可與原有的快速之箭同時使用的個人攻擊速度強化技能「風之祈禱」。提高隊員攻擊速度的支援能力維持為拳霸的獨有角色，破風使者則以強化自身攻擊速度的方式加以區分。藉此在區隔兩個職業支援角色的同時，也能強化破風使者專屬的快速射擊能力。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["攻擊速度","無","提升2階段"],["適用對象","無","僅限自身"],["持續時間","無","110~300秒"]]}]},"WindBreaker|進階暴風":{"tags":["新增"],"comment":"為了讓破風使者在成長過程中能以更強大的方式運用風之精靈「暴風」，新增「進階暴風」。一轉時是直接召喚精靈輔助戰鬥，四轉時則發展為將精靈之力注入弓中，強化暴擊機率與暴擊傷害。\n\n此外，與原作不同，為了讓不再需要變身的「阿爾法」也能直接參與戰鬥，我們新增了特殊效果：使用「疾風光速神弩」或「疾風掃射」時，阿爾法會每隔一段時間現身，使用相同技能一同攻擊。隨著技能等級提升，阿爾法現身的頻率也會增加，進一步協助破風使者施展主要攻擊技能。","notes":[["召喚石消耗","每次使用暴風消耗1顆召喚石。"],["阿爾法追加攻擊","使用「疾風光速神弩」或「疾風掃射」時，阿爾法會現身，並使用相同技能追加一次攻擊。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["暴擊機率增加","無","1~10%"],["暴擊傷害增加","無","1~30%"],["持續時間","無","300秒"],["物理防禦力與魔法防禦力增加","無","25"],["冷卻時間","無","15~3秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["暴擊機率增加","無","10%","新增"],["暴擊傷害增加","無","30%","新增"],["阿爾法追加攻擊冷卻時間","無","3.0秒","新增"]]}]}]},"WindBreaker|疾風光速神弩":{"tags":["新增"],"comment":"承襲原作破風使者的代表性攻擊技能「疾風光速神弩」，將其設計為四轉的主力多目標攻擊技能。以強力的一箭貫穿前方多名敵人，並設計為可在阿爾法狀態下使用。此外，可透過風影漫步在空中發射，同時運用移動與強力的貫穿攻擊。","notes":[["使用條件","僅限阿爾法增益效果期間使用。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","132~770%"],["攻擊目標數量","無","3~6名"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["傷害","無","770%","新增"]]},{"name":"攻擊目標數量","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","3隻","新增"],["Lv.6~10","無","4隻","新增"],["Lv.11~15","無","5隻","新增"],["Lv.16~30","無","6隻","新增"]]}]}]},"WindBreaker|疾風掃射":{"tags":["新增"],"comment":"在承襲原作破風使者的代表性攻擊技能「疾風掃射」的同時，設計為可作為成長至200級的弓箭手之主力單一目標攻擊技能。\n\n若說「疾風光速神弩」是貫穿多隻怪物的強力攻擊，「疾風掃射」則是對單一敵人集中射出三支箭的連續射擊技能。此外，在阿爾法狀態下可進行空中射擊，希望提供能快速移動、調整與敵人的距離並持續施展強力單體攻擊的破風使者專屬戰鬥方式。","notes":[["攻擊","對一名敵人攻擊3次。"],["使用條件","僅限阿爾法增益效果期間使用。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","264~404%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["單次攻擊傷害","無","404%","新增"],["3次攻擊合計","無","1212%","新增"]]}]}]},"WindBreaker|楓葉淨化":{"tags":["新增"],"comment":"為了讓破風使者能擺脫誘惑或封印等異常狀態並持續射擊，新增「楓葉淨化」。與冒險家的「楓葉淨化」相同，可解除特定異常狀態。","notes":[]},"NightWalker|幻體功":{"tags":["新增"],"comment":"為了讓玩家具備使用飛鏢的盜賊所需的基本命中能力與迴避能力，新增「幻體功」。提供與冒險家盜賊相同的效果，支援穩定的攻擊與生存。","notes":[]},"NightWalker|鷹之眼":{"tags":["新增"],"comment":"新增可提升飛鏢等投擲武器攻擊射程的「鷹之眼」。提供與冒險家盜賊相同的效果。","notes":[]},"NightWalker|黑暗雷鳥":{"tags":["新增"],"comment":"為了展現暗夜行者與黑暗精靈並肩作戰的特色，新增「黑暗雷鳥」。召喚出的精靈會攻擊周圍的敵人並提高物理與魔法防禦力。此外，設計為在高階轉職後能將精靈之力與暗影蝙蝠相結合，進一步發展。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["精靈的目標數量","無","最多3名"],["精靈攻擊力","無","21~40"],["持續時間","無","158~300秒"],["物理防禦力與魔法防禦力增加","無","10~25"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["精靈攻擊力","無","40","新增"],["持續時間","無","300秒","新增"],["MP消耗","無","20","新增"]]},{"name":"物理防禦力、魔法防禦力增加","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","10","新增"],["Lv.6~10","無","15","新增"],["Lv.11~15","無","20","新增"],["Lv.16~20","無","25","新增"]]}]}]},"NightWalker|隱身術":{"tags":["新增"],"comment":"為了讓暗夜行者能運用盜賊職業特有的隱身能力，新增「隱身術」。與冒險家盜賊相同，設計為可藏身於陰影之中以躲避敵人的攻擊。","notes":[]},"NightWalker|雙飛斬":{"tags":["新增"],"comment":"新增投擲兩枚飛鏢攻擊敵人的「雙飛斬」。提供與冒險家盜賊相同的攻擊性能，是暗夜行者連續投擲攻擊起點的基本技能。","notes":[],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["傷害 （單枚飛鏢）","無","150%","新增"],["2枚合計","無","300%","新增"],["MP消耗","無","16","新增"]]}]}]},"NightWalker|精準暗器":{"tags":["新增"],"comment":"新增提高飛鏢攻擊熟練度的「精準暗器」。提供與冒險家刺客相同的效果。","notes":[]},"NightWalker|極速暗殺":{"tags":["新增"],"comment":"為了讓暗夜行者能更快速地投擲飛鏢，新增「極速暗殺」。與冒險家刺客相同，使拳套的攻擊速度提升一個階段，支援連續的飛鏢攻擊。","notes":[],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["持續時間","無","300秒","新增"],["HP、MP消耗 （各自）","無","10","新增"]]}]}]},"NightWalker|強力投擲":{"tags":["新增"],"comment":"為了讓玩家具備運用飛鏢的暴擊攻擊能力，新增「強力投擲」。提供與冒險家刺客相同的效果，並成為之後運用更多樣暴擊攻擊效果的基礎。","notes":[],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["暴擊機率","無","50%","新增"],["暴擊傷害","無","200%","新增"]]}]}]},"NightWalker|速度激發":{"tags":["新增"],"comment":"為了讓暗夜行者能運用快速移動與機動性，新增「速度激發」。與冒險家刺客相同，提高自身與隊員的移動速度及跳躍力，將技能提升至最高等級後，也會新增至帳號的祝福技能中。","notes":[["祝福的速度激發","將速度激發提升至20級後，將新增至帳號的祝福技能中。"]],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["移動速度","無","40","新增"],["跳躍力","無","20","新增"],["持續時間","無","300秒","新增"]]},{"name":"MP消耗","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","無","15","新增"],["Lv.11~20","無","30","新增"]]}]}]},"NightWalker|三飛閃":{"tags":["新增"],"comment":"暗夜行者在承襲原有飛鏢盜賊戰鬥方式的同時，被設計為隨著成長連續投擲更多飛鏢的攻擊結構。為此，於二轉新增「三飛閃」，使攻擊由雙飛斬的兩枚發展為三枚的連續投擲。之後在高階轉職中也會習得飛鏢數量增加的攻擊技能，延續暗夜行者獨有的成長脈絡。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","68~160%"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["傷害 （單枚飛鏢）","無","160%","新增"],["3枚合計","無","480%","新增"],["MP消耗","無","20","新增"]]}]}]},"NightWalker|吸血":{"tags":["新增"],"comment":"這是原作中的二轉主力練功技能「吸血」，在怪物密集的練功場也能同時兼顧攻擊與HP恢復。可連續攻擊最多6名敵人，並恢復攻擊所造成傷害的一部分。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","11~30%攻擊4次"],["目標數量","無","3~6名"],["HP吸收","無","傷害的1~4%"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["傷害","無","30%","新增"]]},{"name":"目標數量","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","3隻","新增"],["Lv.6~10","無","4隻","新增"],["Lv.11~15","無","5隻","新增"],["Lv.16~20","無","6隻","新增"]]},{"name":"HP吸收 （傷害的%）","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","1%","新增"],["Lv.6~10","無","2%","新增"],["Lv.11~15","無","3%","新增"],["Lv.16~20","無","4%","新增"]]},{"name":"MP消耗","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","10","新增"],["Lv.6~10","無","16","新增"],["Lv.11~15","無","22","新增"],["Lv.16~20","無","28","新增"]]}]}]},"NightWalker|藥劑精通":{"tags":["新增"],"comment":"為了讓暗夜行者能更有效率地運用恢復道具與狀態變化道具，新增「藥劑精通」。與冒險家暗殺者相同，強化部分道具的恢復效果與持續時間。","notes":[]},"NightWalker|影網術":{"tags":["新增"],"comment":"為了在多隻怪物靠近的情況下也能持續進行遠距離攻擊，新增「影網術」。可在一定時間內束縛最多6隻怪物，限制其移動。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["目標數量","無","最多6名"],["成功機率","無","42~80%"],["束縛時間","無","5~8秒"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["成功機率","無","80%","新增"]]},{"name":"束縛時間","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","5秒","新增"],["Lv.6~10","無","6秒","新增"],["Lv.11~15","無","7秒","新增"],["Lv.16~20","無","8秒","新增"]]},{"name":"MP消耗","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","10","新增"],["Lv.6~10","無","14","新增"],["Lv.11~15","無","18","新增"],["Lv.16~20","無","22","新增"]]}]}]},"NightWalker|暗影蝙蝠":{"tags":["新增"],"comment":"為了讓暗夜行者能運用與原有飛鏢盜賊有所區別的攻擊方式，新增「暗影蝙蝠」。以飛鏢攻擊敵人時會產生暗影蝙蝠，產生的蝙蝠之後會回應飛鏢攻擊，有一定機率衝向敵人。藉此設計為可同時運用飛鏢的直接攻擊與暗影蝙蝠的夾擊。","notes":[["蝙蝠生成","使用投擲飛鏢的攻擊技能，每攻擊敵人4次即生成1隻暗影蝙蝠，持續60秒。"],["突擊","每次使用飛鏢攻擊時，每隻蝙蝠皆有35%機率衝向敵人。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["蝙蝠數量上限","無","1~3隻"],["蝙蝠傷害","無","53~140%"]]}],"lv":[{"title":"各等級數值 （1~40級）","stats":[{"name":"","head":["Lv.40","調整前","調整後","變化"],"rows":[["蝙蝠傷害","無","140%","新增"]]},{"name":"蝙蝠數量上限","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","無","1隻","新增"],["Lv.11~30","無","2隻","新增"],["Lv.31~40","無","3隻","新增"]]}]}]},"NightWalker|風魔手裏劍":{"tags":["新增"],"comment":"為了讓暗夜行者能攻擊多隻怪物，承襲了冒險家暗殺者的「風魔手裏劍」。這是投擲巨大飛鏢貫穿前方多名敵人的攻擊，傷害與冒險家暗殺者相同。","notes":[],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["傷害","無","180%","新增"]]},{"name":"目標數量","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","無","4隻","新增"],["Lv.11~20","無","5隻","新增"],["Lv.21~30","無","6隻","新增"]]},{"name":"MP消耗","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","無","16","新增"],["Lv.11~20","無","23","新增"],["Lv.21~30","無","30","新增"]]}]}]},"NightWalker|四飛閃":{"tags":["新增"],"comment":"為了讓暗夜行者隨著轉職能運用更進一步的連續投擲技術，新增「四飛閃」。這是對單一敵人連續投擲四枚飛鏢的攻擊，在承襲原有飛鏢攻擊特色的同時增加了攻擊次數。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","86~107%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["傷害 （單枚飛鏢）","無","107%","新增"],["4枚合計","無","428%","新增"],["MP消耗","無","21","新增"]]}]}]},"NightWalker|二段跳":{"tags":["新增"],"comment":"新增可在空中朝行進方向再次躍進的「二段跳」。提供與冒險家暗殺者相同的效果。","notes":[]},"NightWalker|西格諾斯騎士":{"tags":["新增"],"comment":"為了讓皇家騎士團作為可成長至200級的職業具備所需的四轉能力，新增「西格諾斯騎士」。藉由覺醒女皇的祝福強化自身與隊員的所有能力值，並提供與冒險家的「楓葉祝福」相同的效果。","notes":[],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["所有能力值","無","15%","新增"],["持續時間","無","900秒","新增"]]},{"name":"MP消耗","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","10","新增"],["Lv.6~10","無","20","新增"],["Lv.11~15","無","30","新增"],["Lv.16~20","無","40","新增"],["Lv.21~25","無","30","新增"],["Lv.26~30","無","40","新增"]]}]}]},"NightWalker|投擲專家":{"tags":["新增"],"comment":"新增提高雙飛斬、三飛閃、四飛閃、五連投擲熟練度的「投擲專家」。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["熟練度","無","+1~10%"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["四項技能的熟練度","無","60%","新增"]]}]}]},"NightWalker|進階黑暗雷鳥":{"tags":["新增"],"comment":"為了讓暗夜行者在成長過程中，運用黑暗精靈的能力也能與暗影蝙蝠一同發展，新增「進階黑暗雷鳥」。原本是直接召喚黑暗雷鳥精靈輔助戰鬥，習得進階黑暗雷鳥之後，則變更為以增益效果的形式運用精靈之力。現在親自擊敗怪物時有一定機率產生暗影蝙蝠，蝙蝠的暴擊機率也會提高，使持續的飛鏢攻擊與擊敗怪物能延續為更強力的夾擊。","notes":[["召喚石","每次使用黑暗雷鳥消耗1顆召喚石。"],["擊倒時生成蝙蝠","增益效果期間，親自擊倒怪物時有31~60%機率生成1隻暗影蝙蝠。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["持續時間","無","300秒"],["蝙蝠暴擊機率","無","+6~20%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["擊倒時生成蝙蝠的機率","無","60%","新增"],["蝙蝠暴擊機率增加","無","20%","新增"]]}]}]},"NightWalker|蝙蝠交流":{"tags":["新增"],"comment":"為了使暗夜行者能將「暗影蝙蝠」作為強大的攻擊手段，新增了「蝙蝠交流」技能。透過同時增加可持有的蝙蝠數量及每隻蝙蝠的攻擊傷害，讓暗夜行者能施展更強大的毒屬性聯合攻擊。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["蝙蝠數量上限","無","+1~3隻"],["蝙蝠傷害","無","+5~100%"],["蝙蝠攻擊屬性","無","毒屬性"]]}],"lv":[{"title":"各等級數值 （1~20級，以暗影蝙蝠40級為基準）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["蝙蝠傷害增加","無","100%","新增"],["蝙蝠傷害 （暗影蝙蝠40級）","無","280%","新增"]]},{"name":"蝙蝠數量上限增加","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","1隻","新增"],["Lv.6~15","無","2隻","新增"],["Lv.16~20","無","3隻","新增"]]},{"name":"蝙蝠數量上限 （暗影蝙蝠40級）","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","4隻","新增"],["Lv.6~15","無","5隻","新增"],["Lv.16~20","無","6隻","新增"]]}]}]},"NightWalker|躲避":{"tags":["新增"],"comment":"為了讓玩家在應對強敵攻擊的同時獲得反擊的機會，新增「躲避」。迴避攻擊之後，下一次攻擊會套用必定暴擊，使躲避危險攻擊與把握攻擊機會能自然地銜接。","notes":[["迴避後暴擊","迴避後接續的下一次攻擊會套用暴擊。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["迴避機率","無","1~30%"]]}]},"NightWalker|毒炸彈":{"tags":["新增"],"comment":"為了在攻擊多隻怪物的同時也能施加持續傷害，新增「毒炸彈」。劇毒炸彈命中時，周圍的怪物也會受到爆炸傷害，並對命中的目標套用劇毒。對BOSS怪物也同樣能施加劇毒，設計為可在各種戰鬥中運用。","notes":[["濺射","對被炸彈擊中的敵人周圍最多5隻其他敵人，造成相同傷害。"],["劇毒","被命中的敵人會陷入劇毒狀態，也會對BOSS怪物生效。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","104~220%"],["劇毒持續時間","無","5~15秒"],["劇毒攻擊力","無","62~120"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["傷害","無","220%","新增"],["劇毒持續時間","無","15秒","新增"],["劇毒攻擊力","無","120","新增"],["MP消耗","無","35","新增"]]}]}]},"NightWalker|五連投擲":{"tags":["新增"],"comment":"為了展現暗夜行者在黑暗中瞬間射出五枚飛鏢的特色，新增「五連投擲」。在隨著轉職而更加精巧的投擲技術之上，再加入暗影蝙蝠的夾擊，使暗夜行者專屬的連續攻擊得以完成。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","87~129%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["傷害 （單枚飛鏢）","無","129%","新增"],["5枚合計","無","645%","新增"],["MP消耗","無","36","新增"]]}]}]},"NightWalker|楓葉淨化":{"tags":["新增"],"comment":"新增「楓葉淨化」，可解除誘惑與封印等特定異常狀態。效果與冒險家的「楓葉淨化」相同。","notes":[]},"Striker|極限迴避":{"tags":["新增"],"comment":"為了讓以近身攻擊為主力的閃雷悍將能穩定地戰鬥，新增「極限迴避」。與冒險家海盜相同，提高命中率與迴避率，支援基本的攻擊與生存能力。","notes":[]},"Striker|閃電":{"tags":["新增"],"comment":"為了展現閃雷悍將與雷之精靈並肩作戰的特色，新增「閃電」。召喚出的精靈會以雷屬性攻擊周圍的敵人並提高物理與魔法防禦力，並設計為之後在高階轉職中能將精靈之力發展為更強大的雷屬性攻擊。","notes":[["召喚","召喚閃電精靈，以雷屬性攻擊周圍最多3名敵人。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["精靈攻擊力","無","21~40"],["物理防禦力與魔法防禦力增加","無","10~25"],["持續時間","無","158~300秒"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["精靈攻擊力","無","40","新增"],["持續時間","無","300秒","新增"]]},{"name":"物理、魔法防禦力增加","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","10","新增"],["Lv.6~10","無","15","新增"],["Lv.11~15","無","20","新增"],["Lv.16~20","無","25","新增"]]}]}]},"Striker|衝擊拳":{"tags":["新增"],"comment":"為了讓玩家能展開以拳頭進行的近身戰鬥，新增「衝擊拳」。提供與冒險家海盜相同的攻擊性能，並設計為之後習得更強力、更快速格鬥技術之基礎的基本攻擊技能。","notes":[],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["傷害","無","270%","新增"],["MP消耗","無","14","新增"]]}]}]},"Striker|旋風斬":{"tags":["新增"],"comment":"為了讓閃雷悍將從初期就能同時運用單一目標攻擊與多目標攻擊，提供了攻擊周圍怪物的基本格鬥技術。","notes":[],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["傷害","無","190%","新增"]]},{"name":"最大攻擊目標數量","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","3名","新增"],["Lv.6~10","無","4名","新增"],["Lv.11~15","無","5名","新增"],["Lv.16~20","無","6名","新增"]]}]}]},"Striker|衝鋒":{"tags":["新增"],"comment":"為了讓閃雷悍將能迅速搶佔近身戰鬥所需的位置，提供了提高移動速度與跳躍力的基本移動能力。","notes":[]},"Striker|生命擴展":{"tags":["新增"],"comment":"為了讓閃雷悍將作為可成長至200級的近戰輸出職業具備穩定的生存基礎，新增「生命擴展」。與冒險家打手相同，提高升級時的MaxHP增加量。","notes":[]},"Striker|精通指虎":{"tags":["新增"],"comment":"新增提高指虎熟練度與命中率的「精通指虎」。效果與冒險家打手相同。","notes":[]},"Striker|致命快打":{"tags":["新增"],"comment":"為了支援以快速拳擊為主力的閃雷悍將的戰鬥，新增「致命快打」。與冒險家打手相同，使指虎的攻擊速度提升一個階段。","notes":[]},"Striker|雷鳴":{"tags":["新增"],"comment":"為了表現閃雷悍將將雷電之力注入拳頭攻擊敵人的特色，新增「雷鳴」。為所有攻擊賦予雷屬性並無視敵人部分防禦力，奠定了作為雷電格鬥家的戰鬥基礎。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["無視防禦力","無","1~5%"],["持續時間","無","26~300秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["持續時間","無","300秒","新增"]]},{"name":"無視防禦力","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~6","無","1%","新增"],["Lv.7~12","無","2%","新增"],["Lv.13~18","無","3%","新增"],["Lv.19~24","無","4%","新增"],["Lv.25~30","無","5%","新增"]]}]}]},"Striker|颶風飛擊":{"tags":["新增"],"comment":"為了表現閃雷悍將以猛烈上鉤拳掀起旋風、橫掃多名敵人的格鬥技術，新增「颶風飛擊」。提供拳頭之力化為旋風的爽快多目標攻擊。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","176~290%"],["最大攻擊目標數量","無","6名"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["傷害","無","290%","新增"]]},{"name":"MP消耗","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~7","無","18","新增"],["Lv.8~15","無","20","新增"],["Lv.16~22","無","22","新增"],["Lv.23~30","無","24","新增"]]}]}]},"Striker|狂暴衝擊":{"tags":["新增"],"comment":"為了讓閃雷悍將能在快速接近敵人的同時進行攻擊，新增「狂暴衝擊」。與冒險家打手相同，提供向前方突進並攻擊多名敵人的格鬥技術。","notes":[],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["傷害（蓄力至滿時）","無","405%","新增"]]},{"name":"MP消耗","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~4","無","20","新增"],["Lv.5~8","無","24","新增"],["Lv.9~12","無","28","新增"],["Lv.13~16","無","32","新增"],["Lv.17~20","無","36","新增"]]}]}]},"Striker|阿特拉斯":{"tags":["新增"],"comment":"閃雷悍將是以快速拳擊為核心、在貼近敵人的距離進行戰鬥的職業。為了確保這種戰鬥方式所需的基本生存能力，新增「阿特拉斯」。永久降低所受傷害，減輕持續進行近身攻擊過程中產生的傷害負擔。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["受到的傷害降低","無","0.5~10%"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["受到的傷害降低","無","10.0%","新增"]]}]}]},"Striker|衝壓暴擊":{"tags":["新增"],"comment":"此次的閃雷悍將並非單純重複強力拳擊的職業，而是設計為結合快速連續攻擊與暴擊的近戰輸出職業。作為這種攻擊結構基礎的技能，新增「衝壓暴擊」。使攻擊有一定機率觸發暴擊，讓閃雷悍將的快速格鬥技術與致命一擊能一同運用。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["暴擊機率","無","12~40%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["暴擊機率","無","40%","新增"],["暴擊傷害","無","200%","新增"]]}]}]},"Striker|閃電精通":{"tags":["新增"],"comment":"為了表現閃雷悍將更加熟練地運用雷電之力的成長，新增「閃電精通」。強化雷屬性攻擊的威力，使蘊藏於體內的電流能化為強力的攻擊。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["雷屬性傷害","無","+1~10%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["雷屬性傷害增加","無","10%","新增"]]}]}]},"Striker|魔力汲取":{"tags":["新增"],"comment":"為了表現閃雷悍將將殘留在倒下敵人身上的電流吸收為自身魔力的特色，新增「魔力汲取」。在擊敗敵人的同時回收雷電之力，補充下一次攻擊所需的MP。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["恢復機率","無","10~40%"],["MP恢復","無","10~20"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["恢復機率","無","40%","新增"],["MP恢復","無","20","新增"]]}]}]},"Striker|閃光擊":{"tags":["新增"],"comment":"為了強化閃雷悍將在拳擊中結合雷屬性追加打擊的特色，新增「閃光擊」。使被攻擊的敵人與周圍的怪物受到雷屬性追加攻擊，設計為可同時運用近身格鬥與多目標攻擊。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","82~120%"],["最大攻擊目標數量","無","2~3名"],["持續時間","無","63~300秒"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["傷害","無","120%","新增"],["持續時間","無","300秒","新增"]]},{"name":"最大攻擊目標數量","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","無","2名","新增"],["Lv.11~20","無","3名","新增"]]}]}]},"Striker|閃電重擊":{"tags":["新增"],"comment":"為了在承襲原作閃雷悍將格鬥技術的同時能使用更強力的單一目標攻擊，新增「閃電重擊」。這是以蘊含雷電之力的拳頭強力攻擊前方一名敵人的技術，提供由基本的衝擊拳發展而來的格鬥攻擊。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","267~400%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["傷害","無","400%","新增"],["MP消耗","無","21","新增"]]}]}]},"Striker|西格諾斯騎士":{"tags":["新增"],"comment":"為了讓皇家騎士團作為可成長至200級的職業具備所需的四轉能力，新增「西格諾斯騎士」。藉由覺醒女皇的祝福強化自身與隊員的所有能力值，並提供與冒險家的「楓葉祝福」相同的效果。","notes":[],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["所有能力值","無","15%","新增"],["持續時間","無","900秒","新增"]]},{"name":"MP消耗","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","10","新增"],["Lv.6~10","無","20","新增"],["Lv.11~15","無","30","新增"],["Lv.16~20","無","40","新增"],["Lv.21~25","無","30","新增"],["Lv.26~30","無","40","新增"]]}]}]},"Striker|雷霆意志":{"tags":["新增"],"comment":"為了在與強大BOSS怪物的近身戰鬥中能穩定維持攻擊節奏，新增「雷霆意志」。技能達最高等級時可防止一般的擊退，支援玩家在近距離持續施展主力攻擊。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["不被擊退的機率","無","35~100%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["不被擊退的機率","無","100%","新增"],["持續時間","無","300秒","新增"]]}]}]},"Striker|進階閃電":{"tags":["新增"],"comment":"為了讓雷之精靈「閃電」的力量能發展為更強大的攻擊能力，新增「進階閃電」。不再直接召喚精靈，而是以增益效果的形式運用雷電之力，並設計為與閃光擊同時套用時，強化追加攻擊的範圍、目標數與傷害。","notes":[["使用閃電","每次使用閃電會消耗1顆召喚石，並以進階閃電增益效果取代精靈召喚。"],["閃光擊範圍","閃光擊的橫向與縱向範圍皆擴大為2倍。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["閃光擊最大攻擊目標數量","無","4~6名"],["閃光擊傷害","無","+1~30%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["閃光擊傷害增加","無","30%p","新增"]]},{"name":"閃光擊最大攻擊目標數量","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","無","4名","新增"],["Lv.11~20","無","5名","新增"],["Lv.21~30","無","6名","新增"]]}]}]},"Striker|閃電疾拳":{"tags":["新增"],"comment":"此次的閃雷悍將比起強力的單次攻擊，更設計為以快速出拳與暴擊攻擊連續銜接的近戰輸出職業。為了實現這樣的戰鬥體驗，新增四轉的全新主力攻擊技能「閃電疾拳」。閃電疾拳將單次攻擊的傷害設定得相對較低，取而代之的是以極短的間隔反覆出拳。藉此展現不斷打擊敵人的格鬥速度感與打擊手感，並希望完成閃雷悍將運用暴擊攻擊的專屬戰鬥方式。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","96~125%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["傷害","無","125%","新增"]]},{"name":"MP消耗","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","無","4","新增"],["Lv.11~20","無","5","新增"],["Lv.21~30","無","6","新增"]]}]}]},"Striker|鯨噬":{"tags":["新增"],"comment":"承襲原作閃雷悍將的代表性攻擊技能「鯨噬」，將其設計為四轉的主力多目標攻擊技能。以強力的攻擊貫穿前方多名敵人，使可成長至200級的閃雷悍將在高等級階段也能有效對付多隻怪物。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","275~810%"],["最大攻擊目標數量","無","4~6名"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["傷害","無","810%","新增"]]},{"name":"最大攻擊目標數量","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","無","4名","新增"],["Lv.11~20","無","5名","新增"],["Lv.21~30","無","6名","新增"]]}]}]},"Striker|閃光":{"tags":["新增"],"comment":"為了讓以近身攻擊為主力的閃雷悍將能快速接近敵人，新增「閃光」。設計為瞬間移動至前方附近的敵人面前後進行攻擊，使玩家在拉近與敵人距離的過程中也能運用格鬥技術。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","46~56%最多4名"],["連續使用限制","無","2秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["傷害","無","56%","新增"],["MP消耗","無","9","新增"]]}]}]},"Striker|閃電之軀":{"tags":["新增"],"comment":"為了讓閃雷悍將不僅能將雷電之力用於攻擊，也能用於資源恢復，新增「閃電之軀」。此技能設計為受到敵人的雷屬性攻擊時，將實際受到傷害的一部分轉換為體內的電流以恢復MP。藉此，與透過擊敗怪物恢復MP的「魔力汲取」一同，希望提供在不同戰鬥情況下運用雷電之力的資源恢復能力。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["MP恢復","無","受到傷害的11~40%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["MP恢復（相對於減少的HP）","無","40%","新增"]]}]}]},"Striker|楓葉淨化":{"tags":["新增"],"comment":"為了在近戰中即使陷入危險的異常狀態也能持續戰鬥，新增「楓葉淨化」。與冒險家相同，提供解除特定異常狀態的效果。","notes":[]},"Hero|激勵":{"tags":[],"comment":"改為可與既有的攻擊力增加增益效果疊加生效，並新增魔力增加效果，使其能為更多職業帶來幫助。攻擊力增加量與防禦力降低效果也隨之調整。","notes":[["與其他攻擊力增益效果疊加","現在可與其他攻擊力增益效果同時生效。"],["祝福的激勵","調整為與激勵20級相同的數值。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["增加攻擊力","1~10","1~8"],["新增增加魔力","無","1~10"],["物理防禦力降低","1~10","43~100"],["新增魔法防禦力降低","無","43~100"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["增加攻擊力","10","8","-2"],["增加魔力","無","10","新增"],["物理防禦力降低","10","100","+90"],["魔法防禦力降低","無","100","新增"]]}]}]},"Hero|鬥氣集中":{"tags":[],"comment":"改善原本依技能等級與鬥氣量而以複雜方式計算的傷害增加機制。變更為每1個鬥氣量固定增加傷害，並調整為在較低的技能等級也能更有效地運用。","notes":[["傷害計算","現在擁有鬥氣量時傷害增加6~35%，每1個鬥氣量再追加5%。"],["技能說明","各等級說明中的傷害將依新的計算方式顯示。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["鬥氣量為5個時的傷害倍率","1.21~1.50倍","1.31~1.60倍"],["鬥氣量為1個時的傷害倍率","1.05~1.34倍","1.11~1.40倍"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["鬥氣量為5個時的倍率","1.50倍","1.60倍","+0.10倍"],["鬥氣量為1個時的倍率","1.34倍","1.40倍","+0.06倍"]]}]},{"title":"各鬥氣量數值 （鬥氣集中30級，學習進階鬥氣前）","stats":[{"name":"傷害倍率","head":["鬥氣量","調整前","調整後","變化"],"rows":[["1個","1.34倍","1.40倍","+0.06倍"],["2個","1.38倍","1.45倍","+0.07倍"],["3個","1.42倍","1.50倍","+0.08倍"],["4個","1.46倍","1.55倍","+0.09倍"],["5個","1.50倍","1.60倍","+0.10倍"]]}]}]},"Hero|黑暗斬擊":{"tags":["名稱變更","便利性"],"comment":"原本必須依使用的武器分別學習技能，造成不便。為了改善此問題並提高武器選擇的自由度，將「黑暗之劍」與「黑暗之斧」整合為一個技能。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["可使用的武器","劍","劍與斧"]]}]},"Hero|黑暗之斧":{"tags":["刪除"],"comment":"因技能合併而刪除。","notes":[]},"Hero|氣絕斬":{"tags":["名稱變更","便利性"],"comment":"原本必須依使用的武器分別學習技能，造成不便。為了改善此問題並提高武器選擇的自由度，將「氣絕劍」與「氣絕斧」整合為一個技能。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["可使用的武器","劍","劍與斧"]]}]},"Hero|氣絕斧":{"tags":["刪除"],"comment":"因技能合併而刪除。","notes":[]},"Hero|防禦消除":{"tags":[],"comment":"原本的「防禦消除」僅對自身生效，在組隊戰鬥中的運用較為受限。為了改善此問題並強化英雄的隊伍支援能力，將無視防禦效果擴大至全隊，並提高了數值。此外，將技能提升至最高等級後，帳號的祝福技能將新增「祝福的防禦消除」。","notes":[["新增祝福的防禦消除","將防禦消除提升至20級後，將新增至帳號的祝福技能中。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["適用對象","自身","全體隊員"],["無視防禦力","1~5%","1~20%"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["無視防禦力","5%","20%","+15%"]]}]}]},"Hero|進階鬥氣":{"tags":[],"comment":"為了讓玩家能更直觀地理解依鬥氣量增加傷害的效果，計算方式將有所改善。變更為無論鬥氣量多寡，皆套用與「鬥氣集中」相同的計算方式，因此鬥氣量為5個以下時的傷害倍率將獲得提高。不過，鬥氣量疊加至最大值時的傷害倍率則設定為維持不變。","notes":[["傷害計算","現在無論鬥氣量多寡，皆套用與鬥氣集中相同的計算。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["鬥氣量為1~5個時的傷害倍率","1.64~1.80倍","1.70~1.90倍"]]}],"lv":[{"title":"各等級數值 （1~30級，以鬥氣集中30級為基準）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["鬥氣量為1個時的倍率","1.64倍","1.70倍","+0.06倍"],["鬥氣量為5個時的倍率","1.80倍","1.90倍","+0.10倍"]]}]},{"title":"各鬥氣量數值 （鬥氣集中、進階鬥氣皆為30級）","stats":[{"name":"","head":["10個","調整前","調整後","變化"],"rows":[["傷害倍率","2.15倍","2.15倍","無變更"]]}]}]},"Hero|格擋":{"tags":[],"comment":"為了更加展現冒險家劍士承受敵人攻擊、堅守前線的特色，改善了「格擋」的性能。不被擊退的機率最高提高至100%，使玩家在敵人的攻擊下也能穩定維持戰鬥節奏。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["不被擊退的機率","32~90%","35~100%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["不被擊退的機率","90%","100%","+10%"]]}]}]},"Hero|究極突刺":{"tags":[],"comment":"為了提高「究極突刺」在戰鬥中的運用，新增命中時補充鬥氣量的效果。此外，在「鬥氣爆發」狀態下傷害將增加為3倍，改善為可輔助輸出。","notes":[["新增鬥氣量","現在於鬥氣集中狀態下，以究極突刺擊中敵人即可累積鬥氣量。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增鬥氣爆發期間的傷害","72~130%","216~390%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["鬥氣爆發期間的傷害","130%","390%","+260%"]]}]}]},"Hero|鬥氣爆發":{"tags":[],"comment":"為了更鮮明地突顯英雄強大的單一目標攻擊能力，我們對「鬥氣爆發」進行了調整。將原有的物理攻擊力增加效果替換為攻擊速度增加效果，以提高武器選擇的自由度，並強化「無雙劍舞」與「究極突刺」的攻擊性能，變更為能對一名敵人集中火力。此外，我們提高了鬥氣量的累積效率並移除了冷卻時間，進一步強化英雄運用鬥氣的獨特戰鬥方式。","notes":[["新增鬥氣量累積","鬥氣爆發期間，鬥氣量的累積量為2倍。"],["新增無雙劍舞","鬥氣爆發期間，無雙劍舞僅攻擊前方最近的一名敵人，傷害係數增加10%。"],["與其他攻擊力增益效果疊加","現在可與其他攻擊力增益效果同時生效。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["冷卻時間","360秒","無"],["持續時間","10~240秒","30~180秒"],["施放時間","1秒","0.2秒"],["刪除增加攻擊力","11~26","刪除"],["新增攻擊速度","無","1~15級提升1階段，16~30級提升2階段"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["持續時間","240秒","180秒","-60秒"],["增加攻擊力","26","無","刪除"]]},{"name":"冷卻時間","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~30","360秒","無","-360秒"]]},{"name":"攻擊速度","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~15","無","1階段","新增"],["Lv.16~30","無","2階段","新增"]]}]},{"title":"鬥氣爆發期間的無雙劍舞 （無雙劍舞1~30級）","stats":[{"name":"","head":["30等級","調整前","調整後","變化"],"rows":[["每擊傷害","260%","286%","+26%"]]},{"name":"目標數量","head":["無雙劍舞","調整前","調整後","變化"],"rows":[["1~10等級","1名","1名","無變更"],["11~20等級","2名","1名","-1名"],["21~30等級","3名","1名","-2名"]]}]}]},"Paladin|降魔咒":{"tags":["特效調整"],"comment":"原本的「降魔咒」僅能降低怪物的攻擊力與物理防禦力，在對付強大的BOSS怪物時運用較為受限。為了改善此問題並強化聖騎士的隊伍支援能力，變更為直接降低受到降魔咒影響的怪物所造成的傷害。","notes":[["與其他減傷效果的關係","與主教的喚化術、槍神的炸彈投擲減傷量相加計算。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增降低怪物造成的傷害","無","1~20%"],["刪除怪物攻擊力降低","1~20","刪除"],["刪除怪物物理防禦力降低","1~20%","刪除"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["降低怪物造成的傷害","無","20%","新增"],["怪物攻擊力降低","20","無","刪除"],["怪物物理防禦力降低","20%","無","刪除"]]}]}]},"Paladin|盾防精通":{"tags":[],"comment":"為了讓聖騎士熟練運用盾牌的特色也能延伸至攻擊，以「盾防精通」增加的盾牌防禦力將一併套用於新技能「盾牌之力」的攻擊力計算。藉此，盾牌的熟練程度越高，就越能同時強化防禦與攻擊能力；原有的盾牌防禦力增加效果則維持不變。","notes":[["與盾牌之力的關係","以盾防精通增加的盾牌防禦力也會套用於盾牌之力的攻擊力計算。"]]},"Paladin|祝福護甲":{"tags":["新增"],"comment":"為了讓聖騎士在成長過程中也能發揮防禦型劍士的優勢而進行改善。將原本四轉後才能習得的傷害減少效果移至三轉被動技能，使玩家能從更早的階段開始穩定戰鬥。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增受到的傷害降低","無","0.5~10.0%"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["受到的傷害降低","無","10.0%","新增"]]}]}]},"Paladin|屬性攻擊":{"tags":["特效調整"],"comment":"原本的「屬性攻擊」會因武器不同而有不同的攻擊範圍，使武器選擇受到限制。為了改善此問題，統一了攻擊範圍，並套用了各屬性全新的攻擊特效。此外，配合聖騎士將屬性附加於武器進行戰鬥的特色，變更為以物理攻擊力為基礎的魔法傷害進行攻擊。","notes":[["攻擊範圍","無論武器與動作為何，範圍皆固定，並較原有範圍增加。"],["新增攻擊特效","配合調整後的攻擊範圍，新增攻擊特效。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害類型","物理傷害","魔法傷害"]]}]},"Paladin|烈焰之劍":{"tags":["刪除"],"comment":"因技能合併而刪除。","notes":[]},"Paladin|烈焰衝擊":{"tags":["名稱變更","便利性","特效調整"],"comment":"原先火屬性充能技能需依劍與鈍器分別學習，造成使用上的不便。為改善此問題並提升武器選擇的自由度，將「烈焰之劍」與「烈焰之棍」整合為「烈焰衝擊」。","notes":[["傷害","修正8級的實際傷害低於技能說明的問題。現在與技能說明相同，套用109%。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["可使用的武器","棍","劍與棍"]]}]},"Paladin|寒冰之劍":{"tags":["刪除"],"comment":"因技能合併而刪除。","notes":[]},"Paladin|寒冰衝擊":{"tags":["名稱變更","便利性","特效調整"],"comment":"原先冰屬性充能技能需依劍與鈍器分別學習，造成使用上的不便。為改善此問題並提升武器選擇的自由度，將「寒冰之劍」與「寒冰之棍」整合為「寒冰衝擊」。","notes":[["傷害","修正1~8級的實際傷害低於技能說明的問題。現在與技能說明相同，套用102~109%。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["可使用的武器","棍","劍與棍"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["充能期間的傷害","120%","120%","無變更"]]}]}]},"Paladin|雷鳴之劍":{"tags":["刪除"],"comment":"因技能合併而刪除。","notes":[]},"Paladin|雷鳴衝擊":{"tags":["名稱變更","便利性","特效調整"],"comment":"原先雷屬性充能技能需依劍與鈍器分別學習，造成使用上的不便。為改善此問題並提升武器選擇的自由度，將「雷鳴之劍」與「雷鳴之棍」整合為「雷鳴衝擊」。","notes":[["傷害","修正實際傷害與技能說明不一致的問題。現在與技能說明相同，套用102~125%。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["可使用的武器","棍","劍與棍"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["充能期間的傷害","121.1%","125%","+3.9%"]]}]}]},"Paladin|盾牌之力":{"tags":["新增"],"comment":"新增被動技能「盾牌之力」，讓盾牌的性能也能影響攻擊能力。裝備的盾牌防禦力越高，額外的物理攻擊力也會隨之增加，為盾牌的選擇與成長賦予新的價值。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增物理攻擊力增加（依盾牌防禦力計算）","無","1~10%"]]}],"lv":[{"title":"各等級數值 （1~10級）","stats":[{"name":"","head":["Lv.10","調整前","調整後","變化"],"rows":[["依盾牌防禦力增加物理攻擊力","無","10%","新增"]]}]},{"title":"盾牌防禦力84時增加的物理攻擊力（1~10級）","stats":[{"name":"","head":["Lv.10","調整前","調整後","變化"],"rows":[["盾防精通20級時","無","17","新增"],["未學習盾防精通時","無","9","新增"]]}]}]},"Paladin|武神防禦":{"tags":["刪除"],"comment":"為了讓聖騎士能從更早的成長階段開始運用傷害減少效果，將原本「武神防禦」的效果移至三轉技能「祝福護甲」。因此，「武神防禦」將被移除。","notes":[]},"Paladin|究極神盾":{"tags":["刪除"],"comment":"原本的「究極神盾」提供以一定機率防禦攻擊的效果，但這次調整變更了技能方向，讓盾牌也能積極運用於攻擊。因此，「究極神盾」將被移除，並由攻擊力依盾牌防禦力比例增加的「盾牌之力」取代。","notes":[]},"Paladin|屬性強化":{"tags":[],"comment":"將「屬性強化」技能說明中顯示的傷害修正為實際套用的數值290~380%。實際傷害與昏迷機率等原有效果維持不變。","notes":[["技能說明","技能說明中的傷害修正為實際數值290~380%。實際傷害維持不變。"]]},"Paladin|格擋":{"tags":[],"comment":"為了強化冒險家劍士在敵人攻擊下也不易被擊退的特性，提高「格擋」不被擊退的機率。技能達最高等級時，不被擊退的機率將提高至100%，使戰鬥更加穩定。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["不被擊退的機率","32~90%","35~100%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["不被擊退的機率","90%","100%","+10%"]]}]}]},"Paladin|聖靈之劍":{"tags":["刪除"],"comment":"因技能合併而刪除。","notes":[]},"Paladin|聖靈之棍":{"tags":["便利性","特效調整"],"comment":"原本即使同樣運用聖屬性，也必須依武器分別學習技能，造成限制。為了改善此問題並讓玩家能自由運用劍與鈍器，將「聖靈之劍」與「聖靈之棍」整合為一個技能。此外，為了在與同樣運用聖屬性的全新職業聖魂劍士組隊時能施展更強力的攻擊，新增在獲得「魂之劍」增益效果期間，「聖靈之棍」狀態下所有攻擊的傷害增加的效果。","notes":[["聖魂劍士的魂之劍","獲得魂之劍增益效果時，聖靈之棍期間所有攻擊的傷害增加為1.01~1.2倍。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["可使用的武器","棍","劍與棍"]]}]},"Paladin|聖騎士防禦":{"tags":["新增"],"comment":"為了更加強化聖騎士作為守護隊友的守護者角色，新增「聖騎士防禦」。透過保護全體隊員的傷害減少效果，使隊伍也能應對強大的BOSS攻擊與足以致命的傷害。此外，將技能提升至最高等級後，也能作為帳號的祝福技能使用。","notes":[["新增祝福的聖騎士防禦","將聖騎士防禦提升至30級後，將新增至帳號的祝福技能中。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增受到的所有傷害降低","無","1~20%"],["新增持續時間","無","10~300秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["受到的所有傷害降低","無","20%","新增"],["持續時間","無","300秒","新增"],["MP消耗","無","50","新增"]]}]}]},"Paladin|究極突刺":{"tags":["特效調整"],"comment":"改善為「究極突刺」的攻擊特效會依武器附加的屬性而改變。將套用符合火、冰、雷、聖屬性的特效。","notes":[]},"Paladin|騎士衝擊波":{"tags":[],"comment":"為了更加凸顯聖騎士以武器蘊含的屬性之力施展強力一擊的戰鬥特色，改善「騎士衝擊波」。變更為以物理攻擊力為基礎造成魔法傷害，並同時強化單一目標攻擊能力。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害類型","物理傷害","魔法傷害"],["傷害","370~750%","410~790%"]]}]},"Paladin|鬼神之擊":{"tags":["特效調整"],"comment":"「鬼神之擊」變更為以物理攻擊力為基礎的魔法傷害。此外，以原作的演出為基礎，全新改善了施放動作與攻擊特效。","notes":[["動作","動作改為舉起鐵鎚躍至空中後，向下重擊。"],["施放特效","調整鬼神之擊的施放特效。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害類型","物理傷害","魔法傷害"]]}]},"DarkKnight|龍爆擊":{"tags":["名稱變更","便利性"],"comment":"原本依武器區分的連擊技能整合為「龍爆擊」。現在不必重新投入技能點數，即可同時使用槍與矛，技能傷害也隨之調整。","notes":[["技能說明","各等級說明中的傷害將修正為符合實際數值。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","54~170%","53~150%"],["30級時3次攻擊的總傷害","510%","450%"],["可使用的武器","槍","槍與矛"]]}],"lv":[{"title":"各等級數值 （1~30級，傷害與遊戲說明相同，捨去小數點後數值）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["單次攻擊傷害","170%","150%","-20%"]]},{"name":"攻擊次數（與之前相同）","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~15","2次","2次","無變更"],["Lv.16~30","3次","3次","無變更"]]}]}]},"DarkKnight|矛連擊":{"tags":["刪除"],"comment":"因技能合併而刪除。","notes":[]},"DarkKnight|龍無雙":{"tags":["名稱變更","便利性"],"comment":"原本依武器區分的「龍無雙」整合為一個技能。在維持原有攻擊性能的同時，改善為槍與矛皆可使用。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["可使用的武器","槍","槍與矛"]]}]},"DarkKnight|無雙矛":{"tags":["刪除"],"comment":"因技能合併而刪除。","notes":[]},"DarkKnight|力量消除":{"tags":[],"comment":"「力量消除」的定位變更為在與怪物直接接觸的戰鬥情況下，減少隊員所受傷害的技能。接觸傷害減少效果維持不變，但不再減少怪物與BOSS的攻擊技能所造成的傷害。","notes":[["祝福的力量消除","依相同規則，僅降低與怪物碰撞時受到的傷害。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["適用減傷的傷害類型","所有攻擊造成的傷害","僅限與怪物碰撞時受到的傷害"]]}]},"DarkKnight|格擋":{"tags":[],"comment":"為了強化冒險家劍士在敵人攻擊下也不易被擊退的特性，提高「格擋」不被擊退的機率。技能達最高等級時，不被擊退的機率將提高至100%，使戰鬥更加穩定。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["不被擊退的機率","32~90%","35~100%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["不被擊退的機率","90%","100%","+10%"]]}]}]},"DarkKnight|究極突刺":{"tags":["特效調整"],"comment":"為了更鮮明地呈現黑騎士的戰鬥特性，「究極突刺」的攻擊演出將有所改善。技能施放及命中時出現的特效，將變更為黑騎士特有的紫色演出。","notes":[]},"DarkKnight|暗之靈魂風暴":{"tags":["新增"],"comment":"原本黑騎士主要以三轉習得的「龍爆擊」與「龍無雙」攻擊多名敵人。為了在四轉也延續這種戰鬥方式的特色，同時提供全新的攻擊體驗，新增了繼承這兩個技能攻擊方式的「暗之靈魂風暴」。這是注入暗之靈魂的力量、連續攻擊最多4名敵人的技能，槍與矛皆可使用，設計為不受武器選擇限制，可運用於練功與BOSS戰。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增傷害","無","27~125%"],["新增攻擊","無","最多攻擊4名敵人，每名4次"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["單次攻擊傷害","無","125%","新增"],["4次合計傷害","無","500%","新增"]]},{"name":"MP消耗","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","10","新增"],["Lv.6~10","無","13","新增"],["Lv.11~15","無","16","新增"],["Lv.16~20","無","19","新增"],["Lv.21~25","無","22","新增"],["Lv.26~30","無","25","新增"]]}]}]},"DarkKnight|暗之靈魂":{"tags":[],"comment":"為了整理「暗之靈魂」的技能結構，並與原作的效果組成保持一致，移除依超出MaxHP上限的部分而額外減少傷害的效果。原有的武器熟練度增加效果維持不變。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["刪除依超出MaxHP上限的數值降低傷害","最高10%","刪除"]]}],"lv":[{"title":"各等級數值 （1~10級，以神聖之火30級為基準）","stats":[{"name":"","head":["Lv.10","調整前","調整後","變化"],"rows":[["每超出多少HP降低1%","1500","無","刪除"],["超出HP可降低的傷害上限","10%","無","刪除"]]}]}]},"ArchMageF/P|魔力擴展":{"tags":[],"comment":"將「魔力擴展」技能說明中顯示的MaxMP增加量修正為實際套用的數值4~40。實際增加量維持不變。","notes":[]},"ArchMageF/P|毒術大師 I":{"tags":["新增"],"comment":"原本依怪物MaxHP決定傷害量的中毒方式，存在無法與角色能力值成長直接連結的限制。因此，為了讓中毒發展為火毒系法師的核心攻擊手段，導入了以魔力與INT為基礎的全新中毒體系。玩家可透過新技能「毒術大師」強化中毒效果，並變更為對原本不受中毒影響的BOSS怪物也能附加效果。","notes":[["BOSS怪物","現在中毒也會對BOSS怪物生效。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增中毒基礎攻擊力","無","0.5~2.5"],["中毒傷害計算","怪物MaxHP的1.45~2.5%","（以魔力與INT計算的魔法傷害） x 中毒基礎攻擊力"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["中毒基礎攻擊力","無","2.5","新增"]]}]}]},"ArchMageF/P|緩速術":{"tags":["刪除"],"comment":"為了建立以中毒為核心的技能成長結構，移除「緩速術」，並在相同轉職階段新增「毒術大師 I」。","notes":[["刪除","緩速術將被刪除。"]]},"ArchMageF/P|火焰箭":{"tags":["特效調整"],"comment":"「火焰箭」的特效改以其他版本為基準，改善為更能展現原有火焰魔法的特色。","notes":[]},"ArchMageF/P|毒霧":{"tags":[],"comment":"「毒霧」的中毒效果配合新的「毒術大師」體系進行變更。中毒傷害改為以角色能力值為基礎的魔法傷害，中毒時間與前置技能條件也一併調整。","notes":[["技能說明","配合原有擊中敵人即必定使其中毒的效果，修正技能說明。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["中毒時間","4.4~44秒","10~30秒"],["中毒傷害","怪物MaxHP的1.45~2.5%","依毒術大師的中毒基礎攻擊力計算的魔法傷害"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["中毒時間","44秒","30秒","-14秒"]]}]}]},"ArchMageF/P|魔力激發":{"tags":[],"comment":"修正技能說明，使「魔力激發」1級的傷害顯示為實際套用的數值111%。原有效果維持不變。","notes":[]},"ArchMageF/P|毒術大師 II":{"tags":["新增"],"comment":"為了讓二轉習得的中毒能力在三轉也能進一步強化，新增「毒術大師 II」。中毒的基礎攻擊力會隨技能等級提高，進一步強化以毒魔法為核心成長的火毒系法師特色。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增中毒基礎攻擊力","無","2.5~12"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["中毒基礎攻擊力","無","12.0","新增"]]}]}]},"ArchMageF/P|末日烈焰":{"tags":[],"comment":"強化火毒系法師以毒弱化敵人、再以火焰造成爆發性傷害的戰鬥特色。為此，為「末日烈焰」新增對中毒敵人的額外傷害效果，改善為同時運用中毒與火焰魔法時能施展更強力的攻擊。","notes":[["技能說明","於技能說明中明確標示原有最多攻擊6名敵人的效果。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["基礎攻擊力","62~120","52~110"],["新增對中毒敵人的額外傷害","無","5~25%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["基礎攻擊力","120","110","-10"],["對中毒敵人的額外傷害","無","25%","新增"]]}]}]},"ArchMageF/P|致命毒霧":{"tags":["特效調整"],"comment":"原本的「致命毒霧」著重於設置毒霧來累積中毒傷害。這次調整為可使用毒霧直接攻擊，並擊敗怪物，並變更為中毒傷害會隨角色成長而增強。此外，為了讓玩家能考量設置位置與戰鬥情況來運用毒霧，而非將毒霧大範圍維持於整張地圖，一併調整了中毒效果與最大設置數量。","notes":[["新增毒霧攻擊","毒霧生成時即開始每1秒以毒屬性攻擊附近最多6名敵人。"],["新增毒霧攻擊的擊退","被毒霧的攻擊擊中的怪物不會被擊退。"],["毒霧攻擊次數","對同一目標每秒最多僅攻擊3次。"],["達到毒霧數量上限時","現在仍可生成新的毒霧，並移除最早結束的一個毒霧。"],["特效","毒霧的顯示較原本更淡。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增毒霧基礎攻擊力","無","16~45"],["中毒判定間隔","每4秒","每1秒"],["中毒機率","41~70%","10~40%"],["中毒時間","4.4~44秒","3~30秒"],["中毒傷害","怪物MaxHP的1.45~2.5%","依毒術大師的中毒基礎攻擊力計算的魔法傷害"],["每張地圖的毒霧數量上限","15個","6個"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["毒霧基礎攻擊力","無","45","新增"],["中毒機率","70%","40%","-30%"],["中毒時間","44秒","30秒","-14秒"]]}]}]},"ArchMageF/P|魔法封印":{"tags":["刪除"],"comment":"為了以火毒系法師的中毒能力為核心重新整理三轉技能組成，移除原有的「魔法封印」。並在相同轉職階段新增強化中毒基礎攻擊力的新被動技能「毒術大師 II」。","notes":[["刪除","魔法封印將被刪除。"]]},"ArchMageF/P|火毒合擊":{"tags":["特效調整"],"comment":"為了改善原本傷害會因怪物的屬性抗性與弱點而大幅變動的計算方式，變更「火毒合擊」的屬性套用方式。現在僅會套用火與毒屬性中較有利的一種，並將中毒機率提高至最高100%，加強與毒魔法的連攜。","notes":[["屬性","現在僅套用火與毒之中倍率較高的一種屬性。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["中毒機率","41~70%","70~100%"],["中毒時間","4.4~44秒","10秒"],["中毒傷害","怪物MaxHP的1.45~2.5%","依毒術大師的中毒基礎攻擊力計算的魔法傷害"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["中毒機率","70%","100%","+30%"],["中毒時間","44秒","10秒","-34秒"]]}]}]},"ArchMageF/P|毒術大師 III":{"tags":["新增"],"comment":"為了進一步強化火毒系法師將毒魔法鑽研至極致的特色，新增被動技能「毒術大師 III」。這是完成中毒成長體系的技能，進一步提高中毒的基礎攻擊力，使玩家能運用強力的毒魔法。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增中毒基礎攻擊力","無","12~48"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["中毒基礎攻擊力","無","48.0","新增"]]}]}]},"ArchMageF/P|核爆術":{"tags":["特效調整"],"comment":"原本的「核爆術」必須蓄力才能施展強力攻擊，在戰鬥中的即時應對與連續攻擊上有所限制。為了改善此不便，並能與火毒系法師的火焰及毒魔法自然連攜，變更了技能的攻擊方式。現在不需蓄力即可立即攻擊，並會套用火與毒中較有利的屬性。此外，變更為有一定機率附加中毒，而基礎攻擊力則配合施放方式進行調整。","notes":[["施放方式","現在不需蓄力，按下按鍵即可立即攻擊，按住按鍵則可連續施放。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["基礎攻擊力","160~450","53~146"],["屬性","無屬性","火與毒之中倍率較高的一種屬性"],["新增中毒機率","無","30~60%"],["新增中毒時間","無","3~6秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["基礎攻擊力","450","146","-304"],["中毒機率","無","60%","新增"]]},{"name":"中毒時間","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","3秒","新增"],["Lv.6~15","無","4秒","新增"],["Lv.16~25","無","5秒","新增"],["Lv.26~30","無","6秒","新增"]]}]}]},"ArchMageF/P|魔法反射":{"tags":["刪除"],"comment":"為了強化以中毒為核心的四轉技能組成，移除「魔法反射」，並新增被動技能「毒術大師 III」。","notes":[["刪除","魔法反射將被刪除。"]]},"ArchMageF/P|炎靈地獄":{"tags":["特效調整"],"comment":"原本的「炎靈地獄」僅能附加冰屬性弱點，與其他屬性攻擊的連攜受到限制。為了改善此問題，並讓其也能為運用屬性魔法的隊員做出貢獻，變更為除了冰屬性之外，也能附加雷屬性弱點。此外，將持續傷害從依怪物MaxHP比例計算的方式變更為魔法傷害，並改善為對BOSS怪物也會生效。","notes":[["BOSS怪物","現在持續傷害也會對BOSS怪物生效。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["持續傷害","怪物MaxHP的1.45~2.5%","以基礎攻擊力48計算的魔法傷害"],["弱點屬性","冰","冰與雷"]]}]},"ArchMageF/P|劇毒麻痺":{"tags":["便利性"],"comment":"原本的「劇毒麻痺」與以中毒為核心重新設計的火毒系法師戰鬥結構缺乏直接的連攜。為了改善此問題，新增對中毒敵人造成額外傷害的效果。此外，為了減少必須先使用其他技能附加中毒的麻煩，變更為「劇毒麻痺」命中時必定附加中毒，使其單獨使用也能發揮追加攻擊的效果。","notes":[["新增中毒","現在必定使命中的敵人中毒。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增中毒時間","無","3~6秒"],["新增對中毒敵人追加1次攻擊","無","5~20%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["對中毒敵人追加1次攻擊 （相對於最終傷害）","無","20%","新增"]]},{"name":"中毒時間","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","3秒","新增"],["Lv.6~15","無","4秒","新增"],["Lv.16~25","無","5秒","新增"],["Lv.26~30","無","6秒","新增"]]}]}]},"ArchMageF/P|火流星":{"tags":["便利性"],"comment":"改善為施放「火流星」期間也能使用「瞬間移動」。藉此減少施放過程中的移動限制，並能更靈活地應對敵人的攻擊。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["施放期間使用瞬間移動","施放後約3秒內無法使用","可使用"]]}]},"ArchMageI/L|魔力擴展":{"tags":[],"comment":"修正技能說明，使「魔力擴展」升級時的MaxMP增加量顯示為實際套用的數值4~40。原有效果沒有變化。","notes":[]},"ArchMageI/L|電閃雷鳴":{"tags":[],"comment":"改善為在怪物密集的練功地圖也能更有效地運用「電閃雷鳴」。在維持原有攻擊範圍的同時，變更為可同時攻擊最多8名敵人。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["最大攻擊目標數量","6名","8名"]]}]},"ArchMageI/L|魔力激發":{"tags":[],"comment":"將「魔力激發」技能說明中顯示的1級傷害修正為實際套用的數值111%。實際效果沒有變化。","notes":[]},"ArchMageI/L|冰凍效果":{"tags":["新增"],"comment":"為了強化冰雷系法師連攜冰與雷魔法的戰鬥特色，新增被動技能「冰凍效果」。以雷屬性攻擊冰凍狀態的敵人時，暴擊機率會提高，使玩家能在冰凍敵人後以雷魔法施展更強力的攻擊。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增對冰凍敵人進行雷屬性攻擊的暴擊機率","無","1~30%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["暴擊機率增加","無","30%","新增"]]}]}]},"ArchMageI/L|落雷凝聚":{"tags":["特效調整"],"comment":"原本的「落雷凝聚」雖是施展強力一擊的技能，但受限於較長的施放時間與單一目標攻擊，難以在各種戰鬥情況中運用。為了改善此問題，將施放時間縮短至約一半，並將最多攻擊目標數擴大為3名。基礎攻擊力雖會配合調整，但改善為能與以雷屬性攻擊冰凍敵人的全新戰鬥結構自然連攜。","notes":[["特效","修正落雷凝聚施放特效看起來晃動的問題。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["施放時間","1.14~1.32秒","0.57~0.66秒"],["最大攻擊目標數量","1名","3名"],["基礎攻擊力","84~200","50~120"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["基礎攻擊力","200","120","-80"]]}]}]},"ArchMageI/L|魔法封印":{"tags":["刪除"],"comment":"為了強化冰雷系法師的冰凍連攜能力，移除原有的「魔法封印」，並在相同轉職階段新增「冰凍效果」。","notes":[["刪除","魔法封印將被刪除。"]]},"ArchMageI/L|冰雷合擊":{"tags":["特效調整"],"comment":"原本的「冰雷合擊」會同時套用冰與雷屬性的倍率，傷害會因怪物的屬性相剋而大幅變動。為了改善此問題，變更為僅套用兩種屬性中較有效的一種。此外，僅在以冰屬性攻擊時才會套用冰凍效果，使各屬性的攻擊特性更加明確。","notes":[["屬性","現在僅套用冰與雷之中倍率較高的一種屬性。"],["冰凍","現在僅在以冰屬性套用時，才會使命中的敵人冰凍。"],["技能說明","修正技能說明中的基礎攻擊力，使其與實際數值一致。"]]},"ArchMageI/L|結凍粉碎":{"tags":["新增"],"comment":"為了進一步強化冰與雷魔法的連攜，新增被動技能「結凍粉碎」。雷屬性攻擊也有一定機率使敵人冰凍，並提高對冰凍敵人造成的雷屬性暴擊傷害。藉此進一步提升連攜冰凍與雷屬性攻擊的戰鬥效果。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增雷屬性攻擊時的冰凍機率","無","50~70%"],["新增冰凍時間","無","2~4秒"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["冰凍機率","無","70%","新增"],["暴擊傷害倍率","無","20%","新增"]]},{"name":"冰凍時間","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","無","2秒","新增"],["Lv.6~15","無","3秒","新增"],["Lv.16~20","無","4秒","新增"]]}]}]},"ArchMageI/L|核爆術":{"tags":["特效調整"],"comment":"原本的「核爆術」必須蓄力才能施展強力攻擊，在戰鬥中的即時應對與連續攻擊上有所限制。為了改善此不便，並能與冰雷系法師的冰及雷魔法自然連攜，變更了技能的攻擊方式。現在不需蓄力即可立即攻擊，並改善為以對怪物較有利的屬性進行攻擊。此外，變更為以冰屬性攻擊時可附加冰凍，而基礎攻擊力則配合施放方式進行調整。","notes":[["施放方式","現在不需蓄力，按下按鍵即可立即攻擊，按住按鍵則可連續施放。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["基礎攻擊力","160~450","38~131"],["屬性","無屬性","冰與雷之中倍率較高的一種屬性"],["新增冰凍機率","無","30~60%"],["新增冰凍時間","無","2~4秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["基礎攻擊力","450","131","-319"],["冰凍機率","無","60%","新增"]]},{"name":"冰凍時間","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~8","無","2秒","新增"],["Lv.9~22","無","3秒","新增"],["Lv.23~30","無","4秒","新增"]]}]}]},"ArchMageI/L|魔法反射":{"tags":["刪除"],"comment":"為了強化冰雷系法師的冰凍連攜能力，移除「魔法反射」，並在相同轉職階段新增被動技能「結凍粉碎」。","notes":[["刪除","魔法反射將被刪除。"]]},"ArchMageI/L|寒冰地獄":{"tags":["特效調整"],"comment":"原本的「寒冰地獄」著重於持續傷害與附加屬性弱點，難以直接運用冰與雷魔法的連攜效果。為了改善此問題，新增必定使命中的怪物冰凍的效果，變更為可在之後以雷屬性攻擊運用暴擊效果。此外，在原有的火屬性弱點之外新增毒屬性弱點，強化隊伍的屬性攻擊支援能力，並將持續傷害的計算方式變更為魔法傷害，改善為對BOSS怪物也會生效。","notes":[["BOSS怪物","現在持續傷害也會對BOSS怪物生效。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增冰凍","無","命中的敵人必定冰凍5秒"],["持續傷害","怪物MaxHP的1.45~2.5%","以基礎攻擊力48計算的魔法傷害"],["弱點屬性","火","火與毒"]]}]},"ArchMageI/L|閃電連擊":{"tags":["特效調整"],"comment":"這次調整雖改善為以雷屬性攻擊冰凍敵人時能發揮強力的暴擊效果，但對冰凍無效的BOSS怪物難以運用此效果。為了彌補這一點並強化BOSS戰的攻擊能力，變更了「閃電連擊」的傳導方式。現在即使周圍沒有新的攻擊目標，閃電也會再次傳導至同一敵人，基礎攻擊力與傳導時的傷害減少率也隨之調整。","notes":[["連鎖目標","現在周圍沒有新的攻擊目標時，會再次連鎖至前一次命中的敵人。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["基礎攻擊力","103~190","83~170"],["傳導時的傷害衰減","13%","新的敵人為13%，同一目標的敵人為26%"],["對單獨一名敵人的命中次數","1次","2~4次"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["基礎攻擊力","190","170","-20"]]},{"name":"對單獨一名敵人的命中次數","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~6","1次","2次","+1次"],["Lv.7~12","1次","3次","+2次"],["Lv.13~30","1次","4次","+3次"]]}]}]},"ArchMageI/L|暴風雪":{"tags":["便利性"],"comment":"改善為施放「暴風雪」期間也能使用「瞬間移動」。藉此減少施放過程中的移動限制，並能更靈活地應對敵人的攻擊。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["施放期間使用瞬間移動","施放後約3秒內無法使用","可使用"]]}]},"Bishop|魔力擴展":{"tags":[],"comment":"「魔力擴展」的技能說明中，升級時增加的MaxMP標示與實際不符，現修正為實際套用的數值4~40。原有效果維持不變。","notes":[]},"Bishop|神聖之箭":{"tags":["特效調整"],"comment":"原本的「神聖之箭」作為單一攻擊技能的運用較為受限，使僧侶的練功方式容易集中於「群體治癒」。為了改善此問題，將攻擊次數從原本的1次增加為2次，並提高整體攻擊力，提升其作為聖屬性攻擊技能的運用。","notes":[["技能說明","將明確顯示以聖屬性攻擊單一敵人兩次的內容。"],["特效","修正神聖之箭施放特效位置偏移的問題。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["攻擊次數","1次","2次"],["基礎攻擊力","13~100","7~60"],["單次施放的攻擊力合計","13~100","14~120"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["基礎攻擊力","100","60","-40"],["單次施放的攻擊力合計","100","120","+20"]]},{"name":"攻擊次數","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~30","1次","2次","+1次"]]}]}]},"Bishop|魔法抵抗":{"tags":[],"comment":"為了讓主教不僅能顧及自身生存，也能為減少隊員所受傷害做出貢獻，調整防禦與支援技能的效果。「魔法抵抗」的屬性抗性數值會減少，但新增了透過「喚化術」弱化敵人攻擊的全新支援能力。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["所有屬性抗性","12~50%","7~30%"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["所有屬性抗性","50%","30%","-20%"]]}]}]},"Bishop|神聖祈禱":{"tags":["錯誤修正"],"comment":"「神聖祈禱」原有的經驗值增加效果維持不變。此外，改善了技能說明，以明確說明經驗值效果的套用條件，並可透過新技能「超級神聖祈禱」進一步強化經驗值增加效果。","notes":[["技能說明","於技能說明中明確標示原有的效果：若未組隊或隊伍中沒有祭司或主教，只能發揮一半的效果。"]]},"Bishop|喚化術":{"tags":[],"comment":"原本的「喚化術」僅能降低怪物的移動速度與魔法攻擊力，在對付強大的BOSS怪物時運用較為受限。為了改善此問題並強化主教的隊伍生存支援能力，變更為直接降低受到詛咒的怪物所造成的傷害。此外，改善為對BOSS怪物也會套用詛咒。","notes":[["BOSS怪物","現在也可對BOSS怪物與突襲BOSS生效。"],["與其他減傷效果的關係","與聖騎士的降魔咒、槍神的炸彈投擲減傷量相加計算。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增降低怪物造成的傷害","無","9~15%"],["刪除移動速度降低","31~60%","刪除"],["刪除魔法攻擊力降低","15~25","刪除"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["移動速度降低","60%","無","刪除"]]},{"name":"降低怪物造成的傷害","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","無","9%","新增"],["Lv.11~29","無","12%","新增"],["Lv.30","無","15%","新增"]]},{"name":"魔法攻擊力降低","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","15","無","刪除"],["Lv.11~20","20","無","刪除"],["Lv.21~30","25","無","刪除"]]},{"name":"MP消耗","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","8","8","無變更"],["Lv.11~20","16","16","無變更"],["Lv.21~29","24","16","-8"],["Lv.30","24","24","無變更"]]}]}]},"Bishop|聖龍召喚":{"tags":[],"comment":"原本的「聖龍召喚」是輔助祭司戰鬥的召喚獸，但攻擊性能有限，在練功時的運用略顯不足。為了改善此問題並補強祭司不足的攻擊能力，提高了基礎攻擊力。此外，配合神聖之龍這一技能特色，為攻擊附加聖屬性，變更為可運用聖屬性的怪物相剋。","notes":[["新增聖屬性","聖龍召喚的攻擊改為聖屬性攻擊。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["攻擊力","63~150","84~200"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["基礎攻擊力","150","200","+50"]]}]}]},"Bishop|核爆術":{"tags":[],"comment":"原本的「核爆術」必須蓄力才能施展強力攻擊，在戰鬥中的即時應對與連續攻擊上有所限制。為了改善此不便，並讓主教能更自由地運用攻擊魔法，移除了蓄力方式。現在按下按鍵即可立即攻擊，並新增聖屬性，而基礎攻擊力則配合施放方式進行調整。","notes":[["施放方式","現在不需蓄力，按下按鍵即可立即攻擊，按住按鍵則可連續施放。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["基礎攻擊力","160~450","85~201"],["屬性","無屬性","聖屬性"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["基礎攻擊力","450","201","-249"]]}]}]},"Bishop|魔法反射":{"tags":["刪除"],"comment":"隨著主教四轉技能組成的重新整理，移除原有的「魔法反射」。取而代之的是新增強化隊伍支援能力的新技能。","notes":[["刪除","魔法反射將被刪除。"]]},"Bishop|召喚神龍":{"tags":[],"comment":"原本的「召喚神龍」最多可攻擊3名敵人，在出現大量怪物的練功地圖中運用略為受限。為了改善此問題並補強主教的練功能力，將最多攻擊目標數擴大為4名，使其能同時攻擊更多怪物。","notes":[["技能說明","修正技能說明中的基礎攻擊力，使其與實際數值一致。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["最大攻擊目標數量","3名","4名"]]}]},"Bishop|聖盾護鎧":{"tags":[],"comment":"原本的「聖盾護鎧」是著重於事先預防異常狀態的技能，在應對突如其來的異常狀態時有所限制。為了改善這一點，並讓主教能在危急時刻直接解救隊員，新增了使用技能時立即解除異常狀態的功能。特別是變更為在技能封印狀態下也能使用，改善為在發生誘惑或藥水封印等危險的異常狀態時也能應對。原有的持續時間與冷卻時間也配合調整。","notes":[["新增解除異常狀態","使用後立即解除自己與隊員的封印、虛弱、黑暗、詛咒、誘惑與藥水封印。"],["新增封印期間使用","現在也可於技能封印狀態下使用。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["持續時間","11~40秒","4~15秒"],["冷卻時間","120秒","180~75秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["持續時間","40秒","15秒","-25秒"],["冷卻時間","120秒","75秒","-45秒"]]}]}]},"Bishop|復甦之光":{"tags":[],"comment":"原本的「復甦之光」雖提供強力的復活效果，但因冷卻時間較長，在突襲中能運用的機會有限。為了改善此限制，並更積極地支援隊員重返戰鬥，縮短了冷卻時間。相對地，提高了MP消耗量，使使用技能時的資源管理更加重要。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["冷卻時間","57~30分鐘","19~10分鐘"],["MP消耗","85","5000~2000"]]}],"lv":[{"title":"各等級數值 （1~10級）","stats":[{"name":"","head":["Lv.10","調整前","調整後","變化"],"rows":[["冷卻時間","30分鐘","10分鐘","-20分鐘"],["MP消耗","85","2000","+1915"]]}]}]},"Bishop|天使之箭":{"tags":[],"comment":"主教在支援隊員的攻擊能力上扮演重要角色，但在使用支援技能的過程中，能同時強化自身攻擊能力的手段有限。為了改善此問題，新增了新技能「聖靈祈禱」與「天使之箭」的連攜效果。獲得「聖靈祈禱」增益效果期間，「天使之箭」將變更為攻擊3次，使主教在支援隊伍火力的同時，也能積極參與戰鬥。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增聖靈祈禱增益效果期間的攻擊次數","無","3次"],["新增聖靈祈禱增益效果期間的單發基礎攻擊力","無","76~150"],["新增聖靈祈禱增益效果期間單次施放的攻擊力合計","無","228~450"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["聖靈祈禱增益效果期間的單發基礎攻擊力","無","150","新增"],["聖靈祈禱增益效果期間單次施放的攻擊力合計","無","450","新增"],["一般基礎攻擊力（與之前相同）","240","240","無變更"]]}]}]},"Bishop|天怒":{"tags":["便利性"],"comment":"原本的「天怒」雖具備強力的範圍攻擊能力，但施放過程中移動受限，難以應對危險情況。為了改善此問題，變更為施放期間也能使用瞬間移動。此外，新增使命中的一般怪物昏迷的效果，改善為除了範圍攻擊之外，在組隊練功時也能擔任牽制怪物的角色。","notes":[["新增昏迷","現在會使被天怒擊中的敵人昏迷3秒。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["施放期間使用瞬間移動","施放後約2.7秒內無法使用","可使用"]]}]},"Bishop|聖靈祈禱":{"tags":["新增"],"comment":"原本主教雖擁有恢復、復活、經驗值增加等多種支援能力，但在直接強化隊員攻擊能力方面的作用有限。為了改善這一點，並讓主教能更廣泛地為隊伍戰鬥做出貢獻，新增了新技能「聖靈祈禱」。「聖靈祈禱」會在一定範圍內建立神聖領域，並依施放者的INT比例提高領域內玩家的最終傷害。藉此，隊伍支援能力也會隨主教自身的成長而強化，並能運用以神聖領域為中心共同作戰的全新支援方式。","notes":[["地圖冷卻時間","使用聖靈祈禱的地圖，30秒內所有主教皆無法使用聖靈祈禱。"],["聖靈祈禱增益效果","領域內的所有玩家不論是否同隊，每1秒皆會獲得聖靈祈禱增益效果，離開領域或領域消失後，增益效果仍會維持5秒。"],["最終傷害增加","獲得聖靈祈禱增益效果期間，施放者每1點INT，將使對怪物造成的所有傷害增加0.025%。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["領域持續時間","無","5~20秒"],["冷卻時間","無","60秒"]]}],"lv":[{"title":"各等級數值 （1~10級）","stats":[{"name":"","head":["Lv.10","調整前","調整後","變化"],"rows":[["HP、MP消耗（各自）","無","500","新增"],["領域持續時間","無","20秒","新增"]]},{"name":"冷卻時間","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","無","60秒","新增"]]}]},{"title":"施放者各INT數值的效果 （獲得聖靈祈禱增益效果者的最終傷害）","stats":[{"name":"","head":["1000","調整前","調整後","變化"],"rows":[["最終傷害增加","無","25.00%","新增"]]}]}]},"Bishop|超級神聖祈禱":{"tags":["新增"],"comment":"原本的「神聖祈禱」是提高隊伍經驗值獲得量的代表性支援技能，但在提供增益效果之後，主教親自參與戰鬥與經驗值支援效果之間缺乏連結。為了改善此問題，並為主教積極參與戰鬥賦予意義，新增了新技能「超級神聖祈禱」。對怪物造成傷害可累積神聖力，並可消耗神聖力進一步提高隊員所獲得的「神聖祈禱」經驗值增加效果。藉此強化了與隊員一同參與戰鬥的主教的角色。","notes":[["新增神聖力","每對怪物造成5,000傷害，即可累積1神聖力。上限300"],["使用條件與持續時間","神聖力達10以上時可使用，消耗全部神聖力，每1點神聖力維持1秒。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["神聖祈禱的經驗值效果增加","無","11~30%神聖祈禱生效時，與其經驗值增加量相加套用"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["神聖祈禱的經驗值效果增加","無","30%p","新增"],["與神聖祈禱30級合計的狩獵經驗值增加量","無","80%","新增"]]}]}]},"Bowmaster|致命箭":{"tags":["便利性"],"comment":"「致命箭」的原有效果維持不變，並配合箭神的「箭雨」修正技能說明。","notes":[]},"Bowmaster|烈火箭":{"tags":["特效調整"],"comment":"原本的「烈火箭」是依怪物MaxHP比例決定灼傷傷害的結構，難以充分感受角色能力值與裝備成長所帶來的效果。為了改善這一點，並讓火焰攻擊能作為持續傷害手段運用，變更為灼傷傷害依首次攻擊傷害的比例增加。此外，改善為對原本不受灼傷影響的BOSS怪物也能附加效果，使玩家不僅在練功時，在BOSS戰中也能運用火焰攻擊的特色。","notes":[["新增BOSS怪物","現在灼傷也會對BOSS怪物生效。"],["技能說明","各等級說明中的傷害數值將修正為符合實際倍率。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["灼傷傷害","每1秒造成怪物MaxHP的1.69~2.5%","每1秒造成技能傷害的20~74%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["每次灼傷傷害（相較於首次攻擊傷害）","無","74%","新增"],["單次灼傷 （相對於怪物MaxHP）","2.50%","無","刪除"],["單次灼傷 （相對於能力值視窗的攻擊力）","無","111.1%","新增"]]}]}]},"Bowmaster|箭雨":{"tags":[],"comment":"「箭雨」的技能說明將整理得更為簡潔。最多攻擊6名敵人的原有性能維持不變。","notes":[]},"Bowmaster|四連箭":{"tags":[],"comment":"原本的「四連箭」不論技能等級，攻擊BOSS時皆套用相同的額外傷害，在提升技能的過程中難以感受到該效果的變化。為了改善此問題，變更為攻擊BOSS時的額外傷害會隨技能等級逐步增加。最高等級時則發揮與原本相同的20%效果。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["攻擊BOSS時的傷害","20%","0~20%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["攻擊BOSS時的傷害","20%","20%","無變更"]]}]}]},"Bowmaster|會心之眼":{"tags":["錯誤修正"],"comment":"為了更準確地說明強化隊員暴擊攻擊能力的「會心之眼」效果，整理了技能說明。修正為使說明與實際套用的暴擊傷害數值一致，原有的戰鬥性能沒有變化。","notes":[]},"Bowmaster|暴風神射":{"tags":["錯誤修正"],"comment":"原本的「暴風神射」存在快速重複按下技能鍵的方式比一般連續射擊方式攻擊次數更多的問題。因此，比起按住技能鍵的原本使用方式，依賴重複按鍵的戰鬥反而更有利。為了解決此問題，並讓箭神的代表性連續射擊技能能以原本設計的方式運用，改善了發射結構。同時提高了技能的基礎傷害與攻擊BOSS時的額外傷害，並修正連續射擊時發生的動作與特效錯誤，使戰鬥更加穩定。此外，將追加箭矢的發射機率提高為2倍，讓玩家在聚集多隻怪物的練功地圖中也能更有效地運用。","notes":[["連按輸入","現在即使快速連按按鍵，也不會比按住按鍵時發射更多箭矢。"],["錯誤修正","修正使用暴風神射時可以行走的問題。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","61~110%","66~120%"],["攻擊BOSS時的傷害","10%","1~15%"],["追加箭矢機率","21~50%","42~100%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["傷害","110%","120%","+10%"],["攻擊BOSS時的傷害","10%","15%","+5%"],["追加箭矢機率","50%","100%","+50%"]]}]}]},"Bowmaster|召喚鳳凰":{"tags":[],"comment":"改善為「召喚鳳凰」不僅能直接攻擊，也能作為造成持續傷害的召喚獸運用。被鳳凰攻擊命中的敵人會在一定時間內陷入灼傷狀態，灼傷傷害與持續時間會隨技能等級提高。此外，對BOSS怪物也會生效，可提供持續的攻擊支援。","notes":[["新增灼傷","現在被召喚鳳凰擊中的敵人（包含BOSS怪物）會陷入灼傷狀態。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增灼傷傷害","無","每1秒造成技能傷害的17~54%"],["新增灼傷時間","無","5~15秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["每次灼傷傷害（相較於召喚鳳凰傷害）","無","54%","新增"],["灼傷時間","無","15秒","新增"]]}]}]},"Bowmaster|牽制射擊":{"tags":[],"comment":"原本的「牽制射擊」是降低怪物移動速度的技能，但在移動速度降低效果運用有限的BOSS戰中，難以為隊伍做出貢獻。為了改善這一點，並讓箭神能支援隊伍的攻擊能力，變更為降低怪物迴避率的減益技能。此外，提高了效果套用機率，並改善為對BOSS怪物也會生效，使其在對付強大敵人時也能支援隊員的攻擊命中。","notes":[["新增BOSS怪物","現在也會對BOSS怪物生效。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["生效機率","11~40%","70~100%"],["刪除怪物移動速度降低","1~30%","刪除"],["新增怪物迴避率降低","無","1~10"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["效果觸發機率","40%","100%","+60%"],["怪物移動速度降低","30%","無","刪除"],["怪物迴避率降低","無","10","新增"]]}]}]},"Bowmaster|念力集中":{"tags":[],"comment":"原本的「念力集中」雖提供大幅提高攻擊力的效果，但無法與其他攻擊力增益效果疊加，且有冷卻時間，在組隊戰鬥中的運用較為受限。為了改善此限制，並讓箭神能持續運用自身的攻擊強化效果，變更了技能的結構。降低原有的攻擊力增加量並移除MP消耗減少效果，相對地新增暴擊機率增加效果，並改善為可與其他攻擊力增益效果疊加。此外，移除冷卻時間並支援寵物自動增益效果，變更為在戰鬥中也能穩定維持效果。","notes":[["其他攻擊力增益效果","現在可與其他攻擊力增益效果同時生效。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["冷卻時間","360秒","無"],["持續時間","68~300秒","184~300秒"],["施放時間","0.8秒","0.2秒"],["攻擊力增加","11~26","1~5"],["新增暴擊機率增加","無","1~5%"],["刪除技能MP消耗降低","2~50%","刪除"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["持續時間","300秒","300秒","無變更"],["攻擊力增加","26","5","-21"],["技能MP消耗降低","50%","無","刪除"]]},{"name":"冷卻時間","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~30","360秒","無","-360秒"]]},{"name":"暴擊機率增加","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~4","無","1%","新增"],["Lv.5~11","無","2%","新增"],["Lv.12~19","無","3%","新增"],["Lv.20~26","無","4%","新增"],["Lv.27~30","無","5%","新增"]]}]}]},"Marksman|致命箭":{"tags":["便利性"],"comment":"「致命箭」的技能說明配合神射手的「升龍弩」進行修正。原有的技能效果維持不變。","notes":[]},"Marksman|四連箭":{"tags":[],"comment":"為了重新整理「四連箭」依技能等級成長的結構，調整攻擊BOSS時的額外傷害。原本所有等級皆套用相同的效果，變更後將調整為隨技能等級逐步增加。最高等級時的效果維持與原本相同。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["攻擊BOSS時的傷害","20%","0~20%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["攻擊BOSS時的傷害","20%","20%","無變更"]]}]}]},"Marksman|會心之眼":{"tags":["錯誤修正"],"comment":"改善技能說明，讓玩家能更明確地確認「會心之眼」的暴擊傷害增加效果。修正與實際效果標示不同的數值，原有的戰鬥性能沒有變化。","notes":[]},"Marksman|召喚銀隼":{"tags":["調整"],"comment":"「召喚銀隼」技能說明中的攻擊目標數標示將獲得修正。最多攻擊4名敵人的原有性能沒有變化。","notes":[]},"Marksman|專注弱點":{"tags":[],"comment":"原本神射手即使累積了「必殺狙擊」的集中力，受到攻擊時仍會失去集中力，難以穩定維持強力的攻擊。為了改善此問題，並讓玩家能在想要的瞬間集中攻擊，將原有的「黑暗狙擊」全面調整為「專注弱點」。現在使用技能後會立即將「必殺狙擊」的集中力補至上限，並在一定時間內防止因受到攻擊而減少集中力。藉此減輕累積集中力過程中的負擔，使玩家在重要的戰鬥情況下能穩定發揮「必殺狙擊」的攻擊能力。","notes":[["新增專注力補充","使用後立即將必殺狙擊的專注力補至上限。"],["新增專注力維持","持續時間內，即使受到攻擊，必殺狙擊的專注力也不會減少。"],["刪除敵人命中率降低","移除黑暗狙擊降低敵人命中率的效果。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["冷卻時間","無","180~60秒"],["持續時間","10~300秒","5~15秒"],["施放時間","0.8秒","0.2秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["冷卻時間","無","60秒","新增"],["持續時間","300秒","15秒","-285秒"],["降低敵人命中率的機率","40%","無","刪除"],["敵人命中率降低","30%","無","刪除"]]},{"name":"降低敵人命中率的持續時間","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","5秒","無","刪除"],["Lv.11~20","10秒","無","刪除"],["Lv.21~30","15秒","無","刪除"]]}]}]},"Marksman|必殺狙擊":{"tags":["特效調整"],"comment":"原本的「必殺狙擊」即使透過攻擊累積了集中力，受到攻擊時集中力仍會大幅減少，難以穩定持續強力的攻擊。為了減輕此負擔，並讓集中力能更靈活地運用，改善了技能的結構。將最大集中力從原本的10擴充至最多15，並變更為受到攻擊時僅減少一定量的集中力。依集中力增加的額外傷害與原本相同，最多套用至10，但改善為可累積更多集中力以應對受到攻擊的情況。此外，為了改善每1點集中力的額外傷害低於技能說明標示數值的問題，將實際效果提高至與技能說明的數值一致。","notes":[["新增專注力顯示","畫面上將以數字顯示目前的專注力。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["專注力上限","10","10~15"],["每1點專注力的額外傷害","2.23~66.9%","2.3~69%"],["受攻擊時的專注力","降至1","減少10"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["每1點專注力的額外傷害","66.9%","69%","+2.1%"],["專注力達10以上時的傷害","1439.0%","1460.0%","+21.0%"]]},{"name":"專注力上限","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~3","10","10","無變更"],["Lv.4~9","10","11","+1"],["Lv.10~15","10","12","+2"],["Lv.16~21","10","13","+3"],["Lv.22~27","10","14","+4"],["Lv.28~30","10","15","+5"]]},{"name":"專注力全滿時受攻擊後的剩餘專注力","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~9","1","1","無變更"],["Lv.10~15","1","2","+1"],["Lv.16~21","1","3","+2"],["Lv.22~27","1","4","+3"],["Lv.28~30","1","5","+4"]]}]},{"title":"各專注力數值 （必殺狙擊30級）","stats":[{"name":"","head":["15","調整前","調整後","變化"],"rows":[["傷害","無法累積","1460.0%","新增"]]}]}]},"Shadower|詛咒術":{"tags":[],"comment":"盜賊的一轉技能「詛咒術」的物理防禦力降低數值將有所調整。依技能等級套用的減少量將低於原本，但包含BOSS怪物在內的適用對象與持續時間沒有變化。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["物理防禦力降低","1~10%","1~5%"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["物理防禦力降低","10%","5%","-5%"]]}]}]},"Shadower|血魔轉換":{"tags":["特效調整"],"comment":"「血魔轉換」的施放特效全新變更。原有技能的性能與效果維持不變。","notes":[["施放特效","調整血魔轉換的施放特效。"]]},"Shadower|勇者掠奪術":{"tags":[],"comment":"修正技能說明，使「勇者掠奪術」的楓幣層數累積機率顯示為實際套用的數值27~65%。實際機率維持不變。","notes":[]},"Shadower|瞬身迴避":{"tags":[],"comment":"「瞬身迴避+」的技能名稱變更為「瞬身迴避」。原有的技能效果維持不變。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["名稱","瞬身迴避+","瞬身迴避"]]}]},"Shadower|飛毒殺":{"tags":[],"comment":"原本的「飛毒殺」僅對一般怪物套用中毒效果，在BOSS戰中的運用較為受限。為了改善此問題並強化運用持續傷害的攻擊能力，變更為對BOSS怪物也會套用中毒效果。","notes":[["新增BOSS怪物","現在BOSS怪物也會受到飛毒殺效果。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["對BOSS的成功率","無","11~20%"],["對BOSS的最大疊加層數","無","2次"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["對BOSS的成功機率","無","20%","新增"]]}]}]},"Shadower|致命暗殺":{"tags":["特效調整"],"comment":"原本的「致命暗殺」是在三次攻擊之後自動接續最後一擊的結構，難以中斷攻擊或在想要的瞬間運用最後一擊。為了改善此限制，並讓暗影神偷的攻擊方式更加靈活，將最後一擊分離為獨立技能「補刀」。同時提高「致命暗殺」的攻擊速度並重新調整傷害，使玩家即使不使用最後一擊、僅連續使用「致命暗殺」，也能發揮與原本相近的攻擊性能。藉此改善為可依戰鬥情況選擇快速的連續攻擊與強力的收尾攻擊。","notes":[["刪除最後一擊","最後一擊分離為補刀。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["最高等級","30","20"],["傷害","214~620%","246~425%"],["施放時間","1.25秒","0.625秒"],["攻擊次數","4次","3次"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["傷害","480%","425%","-55%"]]}]}]},"Shadower|補刀":{"tags":["新增"],"comment":"原本「致命暗殺」的最後一擊會在攻擊過程結束後自動發動，難以在想要的瞬間運用。為了改善此限制，並為暗影神偷的攻擊提供更多樣的選擇，將最後一擊分離為獨立技能「補刀」。現在使用「致命暗殺」完成「補刀」的準備後，即可在想要的瞬間於原地，或向左右大幅突進並施展致命攻擊。此外，突進距離比原本的最後一擊更遠，改善為可在攻擊的同時接近敵人，或在迴避的同時對敵人造成傷害等多種運用方式。","notes":[["新增使用條件","僅限處於致命暗殺產生的補刀準備狀態時使用。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","無","478~955%"]]}],"lv":[{"title":"各等級數值 （1~10級）","stats":[{"name":"","head":["Lv.10","調整前","調整後","變化"],"rows":[["傷害","無","955%","新增"]]}]}]},"Shadower|忍影瞬殺":{"tags":["特效調整"],"comment":"原本的「忍影瞬殺」是在一定時間內造成持續傷害的方式，與其他攻擊技能的連攜有限。為了改善此問題並補強暗影神偷的攻擊能力，變更為攻擊敵人時有一定機率由忍者追加攻擊的增益技能。此外，對BOSS怪物也會套用效果，改善為可在各種戰鬥情況中運用。","notes":[["新增追加攻擊","增益效果期間，每個受到攻擊的怪物皆有一定機率遭忍者追加一次攻擊。"],["新增BOSS怪物","現在對BOSS怪物也會觸發。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["技能類型","持續傷害攻擊","增益效果"],["施放時間","2秒","0.8秒"],["持續時間","4~12秒","100~300秒"],["新增追加攻擊機率","無","10~70%"],["新增追加攻擊傷害","無","60~120%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["追加攻擊機率","無","70%","新增"],["追加攻擊傷害","無","120%","新增"],["持續傷害係數","100%","無","刪除"]]},{"name":"持續時間","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","4秒","100秒","+96秒"],["Lv.11~20","8秒","200秒","+192秒"],["Lv.21~30","12秒","300秒","+288秒"]]}]}]},"Shadower|煙霧彈":{"tags":["特效調整"],"comment":"為了更加展現暗影神偷藏身於暗影之中並支援我方攻擊的特色，強化「煙霧彈」的效果。在原有的無敵效果之外新增暴擊機率增加效果，使煙霧在保護隊員的同時，也能作為準備強力攻擊的空間。","notes":[["新增煙霧彈增益效果","對煙霧內的所有玩家賦予煙霧彈增益效果，不受隊伍限制。"],["新增地圖冷卻時間","使用煙霧彈的地圖，240秒內所有暗影神偷皆無法使用煙霧彈。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增暴擊機率增加","無","5~20%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["暴擊機率增加","無","20%","新增"]]}]}]},"NightLord|詛咒術":{"tags":[],"comment":"降低敵人物理防禦力的「詛咒術」效果將有所調整。依技能等級套用的物理防禦力降低量將低於原本，持續時間與同樣會套用於BOSS怪物的效果則維持不變。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["物理防禦力降低","1~10%","1~5%"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["物理防禦力降低","10%","5%","-5%"]]}]}]},"NightLord|恢復術":{"tags":[],"comment":"技能名稱由「恢復術+」變更為「恢復術」。提升HP與MP自然恢復量的效果維持不變。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["名稱","恢復術+","恢復術"]]}]},"NightLord|影分身":{"tags":["特效調整"],"comment":"改善特效，使「影分身」能更自然地跟隨角色的所有動作。以原作為基準整理了分身的動作與位置，原有的攻擊性能沒有變化。","notes":[["技能說明","技能說明中2~29級的傷害將修正為實際數值22~49%。"]]},"NightLord|楓幣攻擊":{"tags":["便利性","特效調整"],"comment":"為了更準確地說明「楓幣攻擊」造成無視怪物防禦力之傷害的效果，整理了技能說明。原有的技能效果維持不變。","notes":[]},"NightLord|飛毒殺":{"tags":[],"comment":"原本的「飛毒殺」是對一般怪物造成持續傷害的效果，但對BOSS怪物無效，運用較為受限。為了改善此限制，並讓夜使者的毒攻擊在BOSS戰中也能發揮作用，變更為對BOSS怪物也能附加中毒。","notes":[["新增BOSS怪物","現在BOSS怪物也會受到飛毒殺效果。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["對BOSS的成功率","無","11~20%"],["對BOSS的最大疊加層數","無","2次"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["對BOSS的成功率","無","20%","新增"]]}]}]},"NightLord|忍影瞬殺":{"tags":["特效調整"],"comment":"原本的「忍影瞬殺」是在一定時間內造成持續傷害的攻擊技能，在與夜使者的其他攻擊技能搭配運用上有所限制。為了改善這一點，並讓忍者同伴能在攻擊過程中一同活躍，將技能效果變更為追加攻擊的增益效果。 現在夜使者每次攻擊敵人時，都有一定機率出現忍者進行追加攻擊，對BOSS怪物也會套用相同的效果。藉此改善為在練功與BOSS戰中，直接攻擊與忍者的夾擊都能自然地銜接。","notes":[["新增追加攻擊","增益效果期間，每個受到攻擊的怪物皆有一定機率遭忍者追加一次攻擊。"],["新增BOSS怪物","現在對BOSS怪物也會觸發。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["技能類型","持續傷害攻擊","增益效果"],["持續時間","4~12秒","100~300秒"],["施放時間","2秒","0.8秒"],["新增追加攻擊機率","無","10~70%"],["新增追加攻擊傷害","無","90~150%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["追加攻擊機率","無","70%","新增"],["追加攻擊傷害","無","150%","新增"],["每1秒造成持續傷害 （2 x （STR + LUK）的%）","100%","無","刪除"]]},{"name":"持續時間","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~10","4秒","100秒","+96秒"],["Lv.11~20","8秒","200秒","+192秒"],["Lv.21~30","12秒","300秒","+288秒"]]},{"name":"施放時間","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~30","2.0秒","0.8秒","-1.2秒"]]}]}]},"NightLord|三飛閃":{"tags":[],"comment":"「三飛閃」技能說明中依LUK增加熟練度的數值標示將重新整理。熟練度隨LUK數值增加的效果與傷害維持不變。","notes":[]},"Buccaneer|昇龍拳":{"tags":[],"comment":"原本的「昇龍拳」專精於單一目標攻擊，在對付大量怪物的練功環境中難以運用。為了改善此限制，並讓玩家能運用多樣的攻擊技能，擴大了攻擊範圍與攻擊目標數，並提高了施放速度。單次攻擊傷害雖比原本降低，但變更為可快速攻擊多名敵人，以提高其作為對付大量怪物的技能的運用。","notes":[["攻擊範圍","前方攻擊範圍略為擴大。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["傷害","110~300%","36~100%"],["最大攻擊目標數量","1名","4~6名"],["施放時間","0.9~1.21秒","0.63~0.96秒"],["刪除連續使用限制","1.78秒","刪除"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["傷害","300%","100%","-200%"]]},{"name":"最大攻擊目標數量","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~5","1隻","4隻","+3隻"],["Lv.6~15","1隻","5隻","+4隻"],["Lv.16~20","1隻","6隻","+5隻"]]}]}]},"Buccaneer|狂暴衝擊":{"tags":[],"comment":"修正技能說明，使「狂暴衝擊」的傷害顯示為實際套用的數值129~405%。實際傷害維持不變。","notes":[]},"Buccaneer|致命暗襲":{"tags":[],"comment":"原本的「致命暗襲」除了攻擊昏迷狀態敵人的效果之外，還包含攻擊BOSS時的傷害增加效果，同時負擔了與技能原本特色略有不同的作用。為了改善此問題並明確區分各技能的定位，將攻擊BOSS時的傷害增加效果移至鬥神系列的增益效果。因此，「致命暗襲」將專注於攻擊昏迷敵人的效果，而攻擊BOSS的能力則變更為透過強化鬥神之力的技能來成長。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["刪除攻擊BOSS時傷害增加","0.5~10%","刪除"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["攻擊BOSS時傷害增加","10.0%","無","刪除"]]}]}]},"Buccaneer|鬥神附體":{"tags":[],"comment":"原本的「鬥神附體」是獲得強大鬥神之力的技能，但因變身使角色外觀被遮住，可使用的攻擊技能也受到限制。為了解決此不便，並讓玩家能更自由地運用鬥神之力，進行了全面調整。現在將維持角色原本的外觀，並改為顯示鬥神的光環，同時移除原有的技能使用限制與冷卻時間。此外，新增攻擊BOSS時的傷害增加效果，改善為不僅在一般戰鬥中，在BOSS戰中也能運用的攻擊強化增益效果。","notes":[["增益效果期間無法使用的技能","現在皆可使用。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["刪除變身","變身為鬥神附體的外觀","刪除"],["施放時間","0.8秒","0.2秒"],["冷卻時間","550~360秒","無"],["新增攻擊BOSS時傷害增加","無","1~10%"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["冷卻時間","360秒","無","-360秒"],["攻擊BOSS時傷害增加","無","10%","新增"]]}]}]},"Buccaneer|衝擊波":{"tags":["便利性","特效調整"],"comment":"原本的「衝擊波」使用變身狀態的攻擊動作，但隨著這次鬥神系列技能調整移除了變身效果，攻擊特效也一併變更。全新套用了施放動作與特效，使角色在維持原有外觀的同時釋放強力的衝擊波。此外，改善為跳躍中也能使用，使移動與攻擊能更靈活地銜接。","notes":[["新增跳躍期間使用","現在也可於跳躍期間使用。"]]},"Buccaneer|魔龍降臨":{"tags":[],"comment":"原本的「魔龍降臨」是攻擊前方敵人的結構，在怪物出現於角色兩側的練功環境中運用受到限制。為了改善此問題，並能運用於多樣的練功方式，將攻擊範圍擴大至後方。此外，新增使命中的一般怪物昏迷的效果，改善為在施展強力範圍攻擊的同時也能牽制怪物的行動，並增加全新練功方式的選擇。","notes":[["新增昏迷","現在命中的敵人必定昏迷3秒。"],["攻擊範圍","現在角色後方也會攻擊與前方相同的距離。"]]},"Buccaneer|鬥神降世":{"tags":[],"comment":"原本的「鬥神降世」雖提供強大的變身能力，但會遮住角色外觀，可使用的攻擊技能也受到限制。為了改善此不便，並讓玩家在四轉也能自由運用鬥神之力，進行了全面調整。現在將維持角色原本的外觀，並改為顯示更強大的鬥神光環，同時移除技能使用限制與冷卻時間。此外，進一步強化「鬥神附體」的BOSS攻擊效果，改善為鬥神的攻擊能力會隨轉職階段發展。","notes":[["增益效果期間無法使用的技能","現在皆可使用。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["刪除變身","變身為鬥神降世的外觀","刪除"],["施放時間","0.8秒","0.2秒"],["冷卻時間","430~240秒","無"],["新增攻擊BOSS時傷害增加","無","11~20%"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["冷卻時間","240秒","無","-240秒"],["攻擊BOSS時傷害增加","無","20%","新增"]]}]}]},"Buccaneer|閃．爆破":{"tags":["特效調整"],"comment":"在維持「閃．爆破」原有攻擊演出的同時，改善為符合「鬥神降世」的全新戰鬥方式。變更為原本的變身模樣以攻擊特效的形式呈現，使其不必將角色外觀實際變為變身狀態，也能呈現原有的攻擊演出。此外，施放時間縮短至一半以下，讓玩家能以更短的間隔持續攻擊。攻擊次數也隨之調整為4次，單次攻擊的傷害維持不變。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["施放時間","2.01~2.64秒","0.80~1.06秒"],["攻擊次數","8次","4次"]]}]},"Buccaneer|閃．索命":{"tags":["特效調整"],"comment":"原本的「閃．索命」是運用變身模樣的攻擊技能，但配合這次「鬥神降世」的調整，整理了演出，使其不必變身也能使用。套用了以角色原本的模樣將敵人拉近的全新攻擊動作，原有的攻擊性能與昏迷效果維持不變。","notes":[["攻擊動作","變更閃．索命的攻擊動作。"]]},"Buccaneer|閃．連殺":{"tags":[],"comment":"原本的「閃．連殺」雖是強力的單一目標攻擊技能，但有「鬥神附體」期間無法使用、且只能攻擊一名敵人的限制。為了解決此不便並提高核心攻擊技能的運用，變更為在鬥神系列增益效果期間也能使用。此外，將最多攻擊目標數擴大為2名，改善為在同時對付多名敵人的戰鬥中也能運用。","notes":[["增益效果期間使用","現在在鬥神附體狀態下也能使用。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["最大攻擊目標數量","1名","2名"]]}]},"Buccaneer|最終極速":{"tags":[],"comment":"原本「最終極速」的技能說明標示會同時消耗HP與MP，但實際上存在只消耗MP的問題。本次修正為技能說明與實際運作一致，現在使用技能時會依說明所示一併消耗HP。提升隊員攻擊速度的效果與持續時間維持不變。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["HP消耗","無","78~40"]]}],"lv":[{"title":"各等級數值 （1~20級）","stats":[{"name":"","head":["Lv.20","調整前","調整後","變化"],"rows":[["HP消耗","0","40","+40"]]}]}]},"Buccaneer|時間置換":{"tags":["便利性"],"comment":"改善為「時間置換」的隊員特效不受其他玩家特效顯示設定的影響，皆會顯示。原有的技能效果維持不變。","notes":[]},"Corsair|雙子星攻擊":{"tags":["錯誤修正"],"comment":"修正使用「雙子星攻擊」等槍械攻擊時，裝備的槍會消失的現象。","notes":[]},"Corsair|炸彈投擲":{"tags":[],"comment":"原本的「炸彈投擲」提供降低怪物攻擊力與物理防禦力的效果，但在突襲中支援隊員生存方面有所限制。為了改善這一點並強化槍神的隊伍支援能力，調整為直接降低怪物所造成傷害的減益技能。現在被「炸彈投擲」命中的怪物所造成的傷害會降低，並可與主教的「喚化術」、聖騎士的「降魔咒」同時套用，為減少隊伍所受傷害做出貢獻。","notes":[["與其他減傷效果的關係","與主教的喚化術、聖騎士的降魔咒減傷量相加計算。"],["搭乘海盜船時使用","現在在搭乘海盜船的狀態下也能使用。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["刪除怪物攻擊力降低","10","刪除"],["刪除怪物物理防禦力降低","10%","刪除"],["新增降低怪物造成的傷害","無","5%"]]}]},"Corsair|偽裝射擊":{"tags":["錯誤修正"],"comment":"「偽裝射擊」技能說明中顯示的昏迷時間將修正為1.5~4.5秒。實際的昏迷效果維持不變。","notes":[]},"Corsair|脫離戰場":{"tags":["錯誤修正"],"comment":"修正技能說明，使「脫離戰場」的傷害顯示為實際套用的數值70~270%。","notes":[]},"Corsair|3連發":{"tags":["錯誤修正"],"comment":"將「3連發」技能說明中顯示的傷害修正為實際套用的數值120~215%。","notes":[]},"Corsair|章魚砲台":{"tags":["特效調整","便利性","錯誤修正"],"comment":"「章魚砲台」的召喚與攻擊演出將以原作為準進行改善。攻擊方向與攻擊目標的選定方式也會一併整理。","notes":[["搭乘海盜船時使用","現在在搭乘海盜船的狀態下也能召喚。"]]},"Corsair|海鷗突擊隊":{"tags":[],"comment":"原本的「海鷗突擊隊」是攻擊單一目標的召喚技能，難以用於對付大量怪物或支援隊伍。為了改善此限制並提高召喚獸的運用，變更為攻擊前方大範圍的技能。現在可同時攻擊最多6名敵人，並對命中的怪物套用「炸彈投擲」的傷害減少效果。藉此改善為運用召喚獸的範圍攻擊與隊伍生存支援能自然地銜接。","notes":[["攻擊範圍","大幅擴大攻擊範圍，可攻擊前方大範圍區域。"],["新增炸彈投擲效果","現在被海鷗突擊隊擊中的敵人，將受到與炸彈投擲相同的效果。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增傷害","無","48~105%"],["最大攻擊目標數量","1名","6名"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["傷害","無","105%","新增"],["攻擊力倍率 （以DEX x 2.5 + STR為基準）","450.0%","無","刪除"]]},{"name":"最大攻擊目標數量","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~30","1隻","6隻","+5隻"]]}]}]},"Corsair|火焰噴射":{"tags":["錯誤修正"],"comment":"原本的「火焰噴射」是依怪物MaxHP比例決定灼傷傷害，難以充分感受角色能力值與裝備成長所帶來的效果。為了改善這一點，並讓火焰攻擊能作為持續傷害手段運用，變更為灼傷傷害依首次攻擊傷害的比例增加。此外，改善為對原本不受灼傷影響的BOSS怪物也能附加效果。","notes":[["新增烈焰膠囊","現在裝備烈焰膠囊時，灼傷傷害也會變為1.5倍。"],["BOSS怪物","現在灼傷也會對BOSS怪物生效。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["單次灼傷傷害","怪物MaxHP的1.45~2.50%","技能傷害的21~50%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["單次灼傷 （相對於怪物MaxHP，無瞬‧冰火連擊）","2.50%","無","刪除"],["單次灼傷 （相對於能力值視窗的攻擊力，無瞬‧冰火連擊）","無","80.00%","新增"],["單次灼傷 （相對於能力值視窗的攻擊力，瞬‧冰火連擊30級）","無","120.00%","新增"],["單次灼傷 （相對於能力值視窗的攻擊力，瞬‧冰火連擊30級，烈焰膠囊）","無","180.00%","新增"]]}]}]},"Corsair|寒霜噴射":{"tags":["錯誤修正"],"comment":"為了強化槍神連攜火焰與寒冰攻擊的戰鬥特色，改善為「寒霜噴射」會對灼傷狀態的敵人造成額外傷害。藉此提高先以「火焰噴射」使敵人陷入灼傷狀態，再以「寒霜噴射」攻擊的戰鬥方式的運用。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增對灼傷狀態敵人的傷害","無","1.21~1.50倍"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["對灼傷狀態敵人的傷害","無","1.50倍","新增"]]}]}]},"Corsair|指定攻擊":{"tags":[],"comment":"原本「指定攻擊」即使標記了目標，能享有傷害增加效果的攻擊也較為受限，在隊伍戰鬥中的支援效果不足。為了改善這項限制並提高標記目標技能的運用價值，將其變更為對一般怪物時，所有玩家都能獲得傷害增加效果。此外，也改善為「章魚砲台」的攻擊同樣會套用「指定攻擊」的傷害增加效果。","notes":[["搭乘海盜船時使用","現在在搭乘海盜船的狀態下也能使用。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["對一般怪物可獲得加成的攻擊","神槍手與槍神的物理攻擊","所有玩家的攻擊"]]}]},"Corsair|瞬‧冰火連擊":{"tags":[],"comment":"原本的「瞬‧冰火連擊」是以提高灼傷計算等級的方式強化「火焰噴射」的持續傷害，但這次調整將灼傷傷害的計算方式變更為依角色的攻擊能力比例計算。配合此變更，「瞬‧冰火連擊」也移除了原有的灼傷計算等級增加效果，調整為直接增加實際灼傷傷害的方式。藉此改善為能更直觀地確認依技能等級強化灼傷的效果。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["新增火焰噴射灼傷傷害增加","無","10~50%"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"灼傷計算等級增加","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~6","1","無","刪除"],["Lv.7~12","2","無","刪除"],["Lv.13~18","3","無","刪除"],["Lv.19~24","4","無","刪除"],["Lv.25~30","5","無","刪除"]]},{"name":"火焰噴射灼傷傷害增加","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~6","無","10%","新增"],["Lv.7~12","無","20%","新增"],["Lv.13~18","無","30%","新增"],["Lv.19~24","無","40%","新增"],["Lv.25~30","無","50%","新增"]]}]}]},"Corsair|砲台章魚王":{"tags":["特效調整","錯誤修正"],"comment":"配合「章魚砲台」的演出改善，「砲台章魚王」的召喚與攻擊演出也將一併改善。召喚位置、攻擊方向與攻擊目標的選定方式，將依與「章魚砲台」相同的基準進行整理。","notes":[]},"Corsair|精準砲擊":{"tags":["錯誤修正"],"comment":"隨著「指定攻擊」的套用基準變更，「精準砲擊」追加的傷害增加效果也將變更為依相同的基準套用。追加效果對一般怪物時套用於所有玩家的攻擊，對BOSS怪物時則套用於神槍手與槍神的攻擊。此外，追加的增加量變更為以施加「指定攻擊」之角色的技能等級為準，改善為尚未學習「精準砲擊」的玩家也能獲得相同的追加效果。","notes":[["可獲得加成的攻擊","現在與指定攻擊相同，對一般怪物時所有玩家的攻擊會獲得額外增加效果。"]]},"Corsair|海鷗特戰隊":{"tags":["特效調整"],"comment":"原本的「海鷗特戰隊」雖是造成強力範圍傷害的攻擊技能，但與其他攻擊技能及隊伍支援效果的連攜有限。為了改善此問題，並能同時運用槍神的多種戰鬥能力，調整為結合範圍攻擊、目標指定與傷害減少效果的技能。現在可攻擊最多15名敵人，並對命中的怪物同時套用「指定攻擊」與「炸彈投擲」的效果。此外，縮短了施放時間，改善為能更快地對大範圍的敵人套用攻擊與支援效果。技能的基礎傷害與MP消耗量也隨之調整。","notes":[["新增指定攻擊與炸彈投擲","現在被炸彈擊中的敵人，將同時受到指定攻擊與炸彈投擲效果。"]],"tables":[{"head":["項目","調整前","調整後"],"rows":[["MP消耗","31~60","155~300"],["傷害","520~1200%","260~600%"],["最大攻擊目標數量","6名","15名"],["施放時間","2.16~3秒","1.512~2.1秒"]]}],"lv":[{"title":"各等級數值 （1~30級）","stats":[{"name":"","head":["Lv.30","調整前","調整後","變化"],"rows":[["MP消耗","60","300","+240"],["傷害","1200%","600%","-600%"]]},{"name":"最大攻擊目標數量","head":["等級","調整前","調整後","變化"],"rows":[["Lv.1~30","6隻","15隻","+9隻"]]}]}]},"Corsair|瞬‧迅雷":{"tags":["錯誤修正"],"comment":"原本的「瞬‧迅雷」存在快速重複按下技能鍵時，會比按住技能鍵發射更多子彈的問題。為了改善此問題，並不論輸入方式皆能提供一致的攻擊性能，修正了連續射擊的結構。此外，也一併改善了連續射擊時發生的部分動作與特效錯誤。","notes":[["連按輸入","現在無論按鍵方式為何，都會以相同速度發射。"],["錯誤修正","修正使用瞬‧迅雷時可以行走或跳躍的問題。"]]},"Corsair|海盜船":{"tags":["便利性"],"comment":"原本「海盜船」在搭乘時可使用的技能有限，若要使用「炸彈投擲」、「指定攻擊」與「章魚砲台」就必須先下船，相當不便。為了消除這項不便，讓玩家能更穩定地運用槍神的核心戰鬥手段，將這三個技能變更為在搭乘「海盜船」的狀態下也能使用。現在無須下船，也能同時運用標記目標、傷害減少效果與召喚獸，讓運用「海盜船」的戰鬥能更自由地持續下去。","notes":[["搭乘時可使用的技能","現在在搭乘海盜船的狀態下也能使用炸彈投擲、指定攻擊、章魚砲台。"]]},"Corsair|海盜加農炮":{"tags":["錯誤修正"],"comment":"修正技能說明，使「海盜加農炮」11~20級的傷害顯示為實際套用的數值270~315%。","notes":[]},"ArchMageI/L|雷閃電鳴":{"tags":[],"comment":"改善為在怪物密集的練功地圖也能更有效地運用「電閃雷鳴」。在維持原有攻擊範圍的同時，變更為可同時攻擊最多8名敵人。","notes":[],"tables":[{"head":["項目","調整前","調整後"],"rows":[["最大攻擊目標數量","6名","8名"]]}]}};
